  str_loading_desc3 = "ตั้งอยู่ที่ทางเหนืออันหนาวเหน็บ ผู้คนสามารถอาศัยอยู่ที่นี่ได้อย่างสงบสุขเพราะพลังเวทแข็งแกร่งที่ปกป้องพื้นที่เล็ก ๆ นี้อยู่ ราชินีเบธเลเฮมจะเป็นผู้ตัดสินใจในเหตุการณ์สำคัญ",
  str_loading_desc4 = "วิกฤตดาร์กโอเวอร์เริ่มเมื่อสิบเจ็ดปีก่อนและถูกพันธมิตรหลายฝ่ายระงับไว้ได้ ทว่าแม้ในชุมชนที่สนิทสนมกันก็ยังมีข้อพิพาทและความเป็นปรปักษ์ต่อกันอยู่ โดยเฉพาะเหล่าออโรเรียน",
  str_loading_desc5 = "ที่อยู่อาศัยของอิคลิพไซท์เพียงแห่งเดียวที่เป็นที่รู้จัก บ้างก็ว่ามีความเกี่ยวข้องกับชิ้นส่วนหลายชิ้นที่ถูกทิ้งไว้ในอารยธรรมโบราณ เราได้แต่เดาว่าอาจมีวี่แววของอิคลิพไซท์อาศัยอยู่ที่นี่ หรือไม่อย่างนั้นก็อาจเป็นฝีมือขององค์กรปริศนา อิคลิพส์...",
  str_loading_desc6 = "เหวลึกที่ไม่มีแสงสว่างใดส่องประกาย ที่ซึ่งสถาปัตยกรรมดูประหลาดและลวงตา และพบงานฝีมือมหัศจรรย์ของยุคโบราณได้เสมอ มีนักผจญภัยมากมายมายังที่แห่งนี้เหมือนแมลงเม่าบินเข้ากองไฟเพื่อหาเรลิกและถ้วยรางวัลของยุคปริศนา แค่เพียงเพื่อมาถูกฝังที่นี่",
  str_loading_desc7 = "หลังวิกฤตดาร์กโอเวอร์มีอิคลิพไซท์โจมตีครั้งมหากาฬเมื่อ 17 ปีก่อน มีเคเลสไทต์จำนวนไม่มากหนีออกจากอีราเวลได้สำเร็จ โซรอซพาเคเลสไทต์ไปซ่อนที่ใต้ดิน แยกตัวจากโลก",
  str_loading_desc8 = "หลายปีก่อน ยามที่อิคลิพไซท์ออกอาละวาด เมืองใต้ดินลึกลงไปนับพันเมตรช่วยชีวิตไว้นับไม่ถ้วน ผู้คนจากเมืองแกนน่อนจัดระเบียบอย่างมีประสิทธิภาพและพัฒนาเทคโนโลยีลูมินาพิเศษขึ้นเพื่อสร้างระบบป้องกันล้อมรอบเมืองแกนน่อน",
  str_loading_desc9 = "ออโรเรียน อิคลิพไซท์ อิลลูมินา ลูโมโพลิส... ข้อมูลในหัวมากเกินไปแล้ว การรวมตัวใหม่ของอิคลิพไซท์จะเกี่ยวข้องกับวิกฤตดาร์กโอเวอร์ที่เกิดขึ้นเมื่อสิบเจ็ดปีก่อนหรือไม่ การเดินทางค้นหาความจริงถูกกำหนดขึ้นให้มีทั้งดีและร้าย",
  str_loading_desc10 = "พันธมิตรพเนจรปากกล้าและไร้ระเบียบจัดตั้งขึ้นมาโดยกลุ่มคนร่อนเร่พเนจร สมาชิกแข็งแกร่งของพันธมิตรส่งกลิ่นราวกับถนนและสายลม ระหกระเหินไปรอบทะเลทรายเรดีเซล ใช้ชีวิตเป็นอิสระโดยไร้กังวลใด",
  str_loading_desc11 = "องค์กรนี้น่าจะเป็นตัวการสร้างวิกฤตดาร์กโอเวอร์ซึ่งมีจุดประสงค์แท้จริงลึกลับไม่มีใครรู้ องค์กรประกอบด้วยอิคลิพไซท์ระดับสูงและรับกบฏจากเผ่าอื่นมากมายด้วยเหตุที่มิอาจรู้ได้ อิคลิพส์หายตัวไปอย่างไร้ร่องรอยหลังจากกองกำลังของนครรัฐต่าง ๆ ร่วมมือกันในภูมิภาคแอสตราเพื่อจัดการวิกฤตดาร์กโอเวอร์",
  str_loading_desc12 = "สร้างขึ้นบนเกาะลอยชื่อ \"แอชูไรต์\" เมืองนี้เป็นป้อมปราการที่ปลอดภัยที่สุดในโลก มันมีลำดับชั้นอำนาจที่โดดเด่นด้วยคนสามคนคือ ผู้ว่าการ สภาผู้อาวุโสจากชนชั้นสูง และนักบวชจากวิหาร ชนชั้นสูงของลูโมโพลิสมุ่งมั่นในการรักษากฎเกณฑ์ปัจจุบัน ในขณะที่วิหารก็ส่งเสริมการบูชาดวงอาทิตย์",
  str_loading_desc13 = "สหพันธรัฐที่ประกอบด้วยการตั้งถิ่นฐานมหาศาลรอบเมืองใต้ดินขนาดใหญ่มีชื่อว่าแกนน่อน อยู่บริเวณแนวหน้าการต่อสู้กับอิคลิพไซท์ สหพันธรัฐอิลลูมินาได้นำระบบคณะผู้นำมาใช้ จัดตั้งรูปแบบสังคมที่แตกต่างจากระบบของลูโมโพลิสโดยสิ้นเชิง",
  str_loading_desc14 = "โคลอสซัส มรดกจากอารยธรรมโบราณ มีความลับมากมายที่กล่าวกันว่าเป็นไปไม่ได้ที่จะวิเคราะห์โครงสร้างและเข้าใจหลักการเบื้องหลัง ไม่แม้กระทั่งความรู้ในปัจจุบันและแม้นักวิชาการจะร่วมมือกันแค่ไหนก็ตาม หลายคนควบคุมโดยตรงไม่ได้ด้วยซ้ำ มีเพียงเคเลสไทต์ที่สามารถเชื่อมโยงกับสติปัญญาของโคลอสซัสได้ด้วยความสามารถทางโทรจิตเพื่อสร้างระดับการควบคุมที่ลึกล้ำและดำเนินการจากที่นั่น",
  str_loading_desc15 = "ความโกลาหลที่เกิดจากวิกฤตดาร์กโอเวอร์ 17 ปีก่อนนำไปสู่ความสูญเสียวัตถุปริศนาหลายอย่างของเคเลสไทต์ ไม่มีใครรู้ว่าพวกมันอยู่ที่ไหน ถึงแม้ว่าวัตถุประสงค์ที่แท้จริงจะถูกปิดบังไว้อย่างรอบคอบ",
  str_loading_desc16 = "เจ้าแห่งเงาหรืออีสต์วานเป็นที่เกรงกลัวมากที่สุดในอัมบราตัน ว่ากันว่าพิพิธภัณฑ์เก็บของสะสมส่วนตัวของเขาอย่างระเบียงเสียงกระซิบ มีของสะสมน่ากลัวจำนวนมากอยู่ ถ้าคุณโชคดีพอที่จะรอดจากอันตรายที่ซ่อนอยู่ใต้อิฐและใยแมงมุม ก็อาจพบสิ่งที่น่าสนใจที่นี่ได้",
  str_loading_desc17 = "ดูเหมือนชาวเมืองอัมบราตันจะมีสองด้าน ก็คือยิ้มแย้มและเย็นชา ใจดีแต่ก็โหดร้าย นี่เป็นเอกลักษณ์ของอัมบราตันด้วย ตราบใดที่คุณปรับตัวได้ ที่นี่ก็เปรียบเสมือนสวรรค์ หากปรับตัวไม่ได้ มันจะเป็นนรก",
  str_loading_desc18 = "ในทวีปแอสตรา มีเรลิกจำนวนนับไม่ถ้วนจากโบราณกาลถูกค้นพบและหนึ่งในนั้นก็คือหอคอยใหม่ที่เพิ่งค้นพบด้วย สิ่งที่ทำให้ผู้คนตกใจไม่ใช่แค่ความสูงของหอคอย แต่เป็นพลังมหัศจรรย์และตำนานเรื่องสมบัติซึ่งซ่อนอยู่ข้างใน",
  str_loading_desc19 = "ผู้ที่ได้รับพลังจากแสงและใช้แสงต่อสู้เป็นพลเมืองหลักของทวีปนี้ นอกจากพวกเขาแล้วก็ยังมีอีกไม่กี่กลุ่มที่สามารถต่อกรกับการร่วมมือของอิคลิพไซท์ได้",
  str_loading_desc20 = "สิ่งมีชีวิตอันไม่ทราบที่มา พวกมันเป็นศัตรูร้ายกาจของทุกชุมชนตั้งแต่จุดเริ่มต้นของยุคประวัติศาสตร์ นอกจากออโรเรียนแล้วยังแทบไม่มีใครรับมือพวกมันไหว",
  str_loading_desc21 = "วัตถุดิบสำหรับทำสัญญาณขอความช่วยเหลือ สามารถใช้อัญเชิญออโรเรียนเข้าร่วมการผจญภัยได้ น่าเสียดายที่ไม่อาจรับประกันได้เลยว่าใครจะตอบรับสัญญาณแบบนี้",
  str_loading_desc22 = "หน้าตาเหมือนเปียโนและสามารถป้อนคำสั่งได้โดยการเล่นบนแผงควบคุมของโคลอสซัสนี้ มีเพียงเคเลสไทต์ที่เข้าใจภาษาของมันได้ดี",
  str_loading_desc23 = "บาเรียธรรมชาติและโคลอสซัสจำนวนมากคอยรักษาความสงบสุขของที่นี่มาหลายร้อยปี\nเช่นเดียวกับเทคโนโลยีโคลอสซัส ต้นกำเนิดของเคเลสไทต์ยังคงคลุมเครือเป็นปริศนาและไม่สามารถยืนยันหาคำตอบได้\nถ้าความสงบสุขนี้คงอยู่ได้ตลอดไป ที่แห่งนี้จะกลับมางอกงามได้อีกครั้งเหมือนในอดีต",
  str_loading_desc24 = "เวลาไม่ได้ช่วยเยียวยาบาดแผลจากเมื่อสิบเจ็ดปีก่อน สิ่งที่เกิดขึ้นในวันนั้นยังคงชัดเจนอยู่ในความเป็นจริงแห่งปัจจุบัน\nนับแต่วันนั้นมา ไม่เคยมีใครกลับมายังสถานที่แห่งนี้อีกเลย... จนกระทั่งวันนี้",
  str_loading_desc25 = "วันนั้นตรงกับเทศกาลใหญ่ และผู้คนก็ไม่ทันได้ตั้งตัว\nการล่มสลายของอีราเวลดูเหมือนจะหลีกเลี่ยงไม่ได้ และชูมเมอร์ก็เป็นแค่ตัวเร่งที่จำเป็นเท่านั้น",
  str_loading_desc26 = "ครั้งหนึ่งอวิดัซเคยเป็นหน่วยพิเศษท่ามกลางฝูงบินโคลอสซัสแห่งอีราเวล\nขนาดที่ใหญ่โตและคุณสมบัติที่หาตัวจับยากทำให้มันมีศักยภาพที่ไร้ขีดจำกัด\nด้วยเหตุนี้ ผู้นำทางของมันจึงต้องรับบทบาทหน้าที่หนักเป็นพิเศษ",
  str_loading_desc27 = "ที่แกนกลางของอวิดัซมีกระสวยรักษาที่สามารถให้การรักษาฉุกเฉินได้เมื่อมีการบาดเจ็บขั้นวิกฤติเจียนตาย\nชูมเมอร์ได้รับการดูแลจากพลังลึกลับและฟื้นฟูพลังขึ้นมาได้เกินความคาดหวังของทุกคน",
  str_loading_desc28 = "พื้นที่มืดอันเต็มเปี่ยมไปด้วยพลังความมืด ตั้งอยู่บริเวณชายแดนของดินแดนรัตติกาลนิรันดร์ มีกลางวันสั้นและกลางคืนยาวนาน\nครั้งหนึ่งเคยเป็นอาณานิคมขนาดใหญ่ของออโรเรียน แต่ถูกละทิ้งไปนานแล้ว ซากปรักหักพังที่ถูกทิ้งร้างกำลังจะพังทลาย ความรุ่งเรืองในอดีตถูกปกคลุมไปด้วยฝุ่นธุลี\nบัดนี้ที่นี่กลายเป็นดินแดนรกร้างอันกว้างใหญ่ที่เกลื่อนไปด้วยเศษซาก เป็นที่อยู่อาศัยของอิคลิพไซท์ ไม่มีออโรเรียนคนใดจะเหยียบย่างกลับไปอีกครั้งเพื่อพบกับความอึดอัดที่เกิดจากพลังความมืด...",
  str_loading_desc29 = "เมืองใต้ดินที่สหพันธรัฐอิลลูมินาสร้างขึ้น ตั้งอยู่ ณ ชายแดนของดินแดนรัตติกาลนิรันดร์เพื่อเป็นปราการสำคัญสำหรับต่อต้านอิคลิพไซท์\nอย่างไรก็ตาม เมืองนี้ถูกทิ้งร้างไปนานแล้วเนื่องจากการบุกรุกของอิคลิพไซท์\nเชื่อว่าในตอนที่กองกำลังของสหพันธรัฐอิลลูมินาถอยทัพ ได้ทิ้งทรัพยากรและอุปกรณ์ไว้มากมาย ทว่าแทบจะไม่มีใครยอมเสี่ยงฝ่าพลังความมืดที่หนักหน่วงและห้วงทะเลของอิคลิพไซท์เพื่อเข้าไปเก็บกู้สิ่งเหล่านั้นเลย",
  str_loading_desc30 = "น้อยคนนักจะรู้จักอุโมงค์ลี้ภัยเก่าแก่แห่งนี้ แต่โชคดีที่มันแข็งแรงพอและยังคงอยู่ในซากปรักหักพังของเมืองใต้ดิน\nนี่อาจเป็นทางเดียวที่จะขึ้นสู่ระดับพื้นผิวโลกได้ จงมุ่งหน้าไปเถอะ\nเอาชนะศัตรูที่ขวางทาง ผ่านเส้นทางอุโมงค์ที่เต็มไปด้วยฝุ่นและกระสุนปืนด้วยความหวังและศรัทธาต่อชีวิต เผชิญกับการต่อสู้ครั้งสุดท้ายที่หลีกเลี่ยงไม่ได้",
  str_loading_h_desc1 = "นี่คือทะเลทรายเรดีเซลแห่งแอสตราตอนใต้ ที่ซึ่งผืนทรายสีทองทอดตัวยาวสุดสายตา\nดินแดนนี้อยู่ภายใต้แสงทองของดวงอาทิตย์ที่แผดเผา ทั้งยังแห้งแล้งโล่งเตียน และเป็นพื้นที่แห่งหนึ่งที่ไม่เหมาะต่อการพำนักที่สุดในแอสตรา\nสิ่งมีชีวิตที่ดื้อด้านและทานทนที่สุดเท่านั้นที่จะพบกับอิสรภาพได้ที่นี่",
  str_loading_h_desc2 = "การจะเข้าถึงดวงตาแห่งพายุที่หุบเขาตาแดงได้นั้นจะต้องเดินทางฝ่าลมพายุที่โหดร้ายและฝนที่กระหน่ำลงมาไม่ขาดสาย\nเถ้าถ่านจากภูเขาไฟที่เคยสร้างความเสียหายไปทั่วทั้งดินแดน ตอนนี้กลับทำหน้าที่เป็นปุ๋ยอย่างดี ทำให้เกิดพื้นที่สีเขียวขจีอันมีชีวิตชีวาแผ่กว้างออกไปไกล\nราวกับว่าโศกนาฏกรรมที่ผ่านมานานแล้วนั้นไม่เคยเกิดขึ้นมาก่อน...",
  str_loading_h_desc3 = "บรรยากาศของห้องปฏิบัติการคอนกรีตใต้ดินแห่งนี้ช่างน่าเบื่อและหดหู่อย่างแท้จริง\nเครื่องมือผ่าตัดกระจัดกระจายอยู่บนโต๊ะกว้าง รูปร่างที่เย็นชาไร้ชีวิตของมันสะท้อนแสงไฟที่แวววับอย่างน่ากลัว\nแต่ก็มีเพียงสถานที่แบบนี้เท่านั้นที่ดอกไม้สุดงดงามจะถือกำเนิดขึ้นมาได้",
  str_loading_h_desc4 = "ในความทรงจำของอีฟ ท้องฟ้าที่บ้านเกิดของเธอเป็นสีฟ้าสดใส ปราศจากเมฆ\nถ้าอะไร ๆ ไม่พลิกผันแบบกะทันหันขนาดนั้น ช่วงเวลาแห่งความสุขอันท่วมท้นอาจคงอยู่ตลอดไปก็ได้\nแค่อาจจะนะ...",
  str_loading_h_desc5 = "ในโอเอซิสแห่งหนึ่งลึกเข้าไปในทะเลทรายเรดีเซล มีถนนสายหนึ่งที่สร้างโดยเรดีเซล เวรนช์\nแม้ว่าถนนสายนี้จะแลดูทรุดโทรม แต่อิฐที่ปรักหักพังทุกก้อนก็เต็มไปด้วยความรัก\nดินแดนขนาดย่อมนี้เป็นสถานที่แห่งหนึ่งที่นุ่มนวลที่สุดในโลก",
  str_loading_h_desc6 = "โรงแรมทีร์คือสถานที่ท่องเที่ยวระดับพรีเมียมของขุนนางแห่งลูโมโพลิส\nสถานที่ที่ดีที่สุดในการดื่มด่ำกับทัศนียภาพชายฝั่งเซเลสเทียอันงดงาม!\nเปิดให้จองแล้วพร้อมรับส่วนลดเวลาจำกัด",
  str_loading_h_desc7 = "ราชันมหาสมุทรคือพิธีบูชาที่มีต้นกำเนิดมาจากชาวออโรเรียนที่ครั้งหนึ่งเคยพำนักอยู่ที่ชายฝั่งแห่งนี้\nผู้เข้าร่วมจะต้องรับบททดสอบจำนวนมากและผ่านการท้าทายต่าง ๆ\nเชื่อกันว่าชัยชนะของพวกเขาจะนำมาซึ่งพร อันได้แก่สภาพอากาศที่ดีและฝูงปลามากมาย",
  str_loading_h_desc8 = "ตำนานโบราณบอกว่ามีปราสาทแห่งหนึ่งที่โผล่ขึ้นมาจากทะเล\nเพื่อช่วยประชาชนของตัวเอง กษัตริย์จึงยอมรับบททดสอบจากเหล่าเทพธิดา\nจากนั้นเวลาก็ได้ดำเนินผ่านไป วิกฤตการณ์นั้นได้ผ่านพ้นมานานแล้ว ทว่ากษัตริย์ก็ยังคงไม่กลับมา",
  str_loading_h_desc9 = "ไม่เป็นที่ชัดเจนว่าพื้นที่แห่งนี้เกิดขึ้นด้วยความตั้งใจของผู้ใด แต่มันคือช่องว่างที่เต็มไปด้วยนิมิตแปลกประหลาด\nภายในนั้นมีผู้คนที่หลับหูหลับตาแสวงหาพลังของผู้กล้าที่หายสาบสูญ และผู้ที่ถวิลหาโอกาสที่จะหนีให้พ้นจากพันธนาการ\nจงน้อมรับคำสาปของคุณและทลายกำแพงมันลงซะ",
  str_loading_h_desc10 = "เมื่อเผชิญหน้ากับความพ่ายแพ้ แคโรไลน์ได้สาปแช่งทุกคนด้วยกำลังกายเสี้ยวสุดท้ายที่เหลืออยู่ของเธอ\nแล้วกษัตริย์ที่เธอพยายามจะชุบชีวิตนั้นก็อาจได้ยินคำวิงวอนนั้นเข้า...",
  str_loading_h_desc11 = "ถึงเวลาที่กองโจรจะย้ายถิ่นฐานอีกครั้งแล้ว\nโจรน่าสงสัยเหล่านี้โผล่มาจากความมืดมิด และกลับเข้าสู่เงามืดอย่างรวดเร็วเช่นเดียวกับตอนที่ปรากฏตัว",
  str_loading_h_desc12 = "ในทะเลทรายร้างที่โล่งเตียนมีหอคอยลาดตระเวนเมืองใต้ดินอิลลูมินาอยู่แห่งหนึ่ง มันตั้งอยู่ที่นี่ตั้งแต่อิลลูมินาสร้างเมืองใต้ดินแห่งนี้และแนวป้องกันขึ้นมา และได้เป็นพยานการต่อสู้ดิ้นรนที่ไม่รู้จักเหนื่อยล้าของเหล่าทหารอิลลูมินาที่เด็ดเดี่ยว",
  str_loading_h_desc13 = "นี่คือสนามรบรอบนอกของเมืองใต้ดิน ทหารอิลลูมินาได้ตั้งป้อมปราการเอาไว้ที่นี่ ว่ากันว่าสามารถหยุดยั้งอิคลิพไซท์ที่เข้ามาโจมตีไม่ให้คืบหน้าต่อไปได้",
  str_loading_h_desc14 = "สถานีขนส่งแห่งนี้อยู่ที่หน้าประตูเมืองใต้ดินหมายเลข 24 และเป็นสถานที่ขนถ่ายสินค้าทั้งขาเข้าและขาออกจากเมือง ถึงแม้ว่าตอนนี้จะไม่มีผู้ใดทำงานอยู่ที่นี่แล้ว แต่ก็มองเห็นได้จากหอคอยที่สูงใหญ่ พาหนะขนส่ง และสินค้ามากมายหลายประเภท ว่าผู้คนที่นี่ใช้ชีวิตกันอย่างกระฉับกระเฉงและมีระบบระเบียบมาก",
  str_loading_h_desc15 = "เมืองใต้ดินอิลลูมินาที่ปล่อยทิ้งร้าง ได้รับความเสียหายอย่างหนักเพราะเกิดเพลิงไหม้ครั้งใหญ่ ชาวเมืองที่เคยอาศัยอยู่ที่นี่ได้รับการอพยพนำตัวไปที่อื่น และทหารที่เคยอาศัยอยู่ที่นี่ก็ต่อสู้อยู่ที่ด่านหน้ากันในเวลานี้ อดีตชาวเมืองแต่ละคนล้วนต่อสู้กันต่อไปในสนามรบของตัวเอง โดยตั้งใจว่าวันหนึ่งจะกลับมาสู่บ้านเกิดของตนเอง",
  str_loading_h_desc16 = "ในอิลลูมินา แม้แต่ตามถนนหนทางก็ยังสว่างเจิดจ้าไปด้วยแสงจากเหล็กกล้า เมื่อได้เห็นเส้นทางนี้เป็นครั้งแรก ใคร ๆ ก็อดไม่ได้ที่จะตั้งข้อสังเกตว่ามันช่างสว่างจ้าเหลือเกิน",
  str_loading_h_desc17 = "เคเลสไทต์มีธรรมเนียมที่น่าสนใจหลายอย่างในช่วงเทศกาลนี้และมักตกแต่งบ้านเรือนกัน\nพวกเขาเชื่อว่านี่เป็นวิธีหนึ่งในการเชื่อมโยงกับธรรมชาติและกับเหล่าบรรพบุรุษ",
  str_loading_h_desc18 = "ประวัติศาสตร์ก็เหมือนกับขนนกที่ติดอยู่ใต้เปลือกหอยอันหนักอึ้ง\nเส้นทางสู่อนาคตขึ้นอยู่กับว่าเราจะนำทางไปข้างหน้าอย่างไร",
  str_loading_h_desc19 = "การค้าเสรีในตลาดเสรี ทุกอย่างสามารถซื้อขายได้ในอัมบราตัน\nกิลด์เป็นศูนย์รวมของการค้าและเงินทุน นำความมีชีวิตชีวาที่ไร้ขอบเขตมาสู่อัมบราตัน",
  str_loading_h_desc20 = "แก๊งใต้ดินของอัมบราตันเป็นที่รู้จักในนาม \"เงาในเงามืด\" ปฏิบัติการภายในพื้นที่สีเทา ไม่สามารถเปิดเผยตัวเองต่อสายตาของสาธารณชนได้ อย่างไรก็ตาม พวกเขาใฝ่ฝันที่จะใช้การโค่นล้มอย่างลับ ๆ ไปสู่ความสำเร็จในชั่วข้ามคืน และเป็นที่ยอมรับในสังคมเป็นวงกว้าง เมื่อเมฆดำก่อตัวเหนือศีรษะ พวกเขาก็เริ่มปฏิบัติการลับทุกรูปแบบ...",
  str_loading_h_desc21 = "เขื่อนแห่งรอยแผลตั้งตระหง่านและภาคภูมิท่ามกลางภัยธรรมชาติหรือหายนะจากน้ำมือมนุษย์ พายุฝนหรือสงคราม ไม่เพียงแต่พิสูจน์ให้เห็นถึงความทนทานต่อผู้สร้างเขื่อนนี้ขึ้นมา นั่นคือเจ้าแห่งเงา แต่ยังทำให้ผู้คนในอัมบราตันรู้สึกปลอดภัยอีกด้วย",
  str_loading_h_desc22 = "ชนชั้นสูงแห่งลูโมโพลิสต่างอวดความมั่งคั่งของตัวเองด้วยความภาคภูมิใจ แม้การแสดงออกถึงความหรูหราฟุ่มเฟือยนั้นจะได้มาจากการทำงานหนักของสามัญชนก็ตาม และเมืองที่อยู่ด้านล่างก็คือสถานที่ที่ประชาชนเหล่านั้นอาศัยอยู่ แม้จะต่างกันคนละโลกกับคฤหาสน์ของชนชั้นสูง แต่ก็มีชีวิตชีวาด้วยความอบอุ่นและกำลังใจที่เด็ดเดี่ยวแน่วแน่ เพราะอย่างไรเสีย นี่ก็ยังเป็นส่วนหนึ่งของลูโมโพลิส แม้มีสถานะต่ำต้อย แต่ผู้คนก็สุขสบายกว่าพวกที่อยู่ภายนอกขอบเขตของเมืองนี้อย่างมาก",
  str_loading_h_desc23 = "เนื่องจากที่นี่เป็นศูนย์กลางอารยธรรมออโรเรียน ลูโมโพลิสจึงถือว่าตัวเองเป็นผู้นำกองกำลังของทวีปนี้\nด้วยเหตุผลนี้เองจึงมีการสร้างโถงแห่งนี้ขึ้นมา\nเพื่อแสดงถึงความแข็งแกร่งและเกียรติยศของลูโมโพลิสให้ผู้นำชาวต่างชาติที่ได้รับเชิญมาเข้าร่วมการประชุม\nสำคัญระดับโลกได้เห็น\nวิธีการนี้ทำให้ลูโมโพลิสคงความเหนือกว่าในการประชุมทั้งหมดที่กองกำลังทั้งหลายเข้ามามีส่วนร่วมและทำการ\nตัดสินใจเรื่องต่าง ๆ จำนวนมหาศาลที่ส่งผลต่อทั้งทวีปให้เป็นไปตามแนวคิดของตนเอง",
  str_loading_h_desc24 = "ดอกไม้ไฟเทศกาลโอบกอดเมืองแอชูไรต์เอาไว้ทั้งเมือง การจัดแสดงที่อลังการนี้ทำให้ผู้คนพากันมาสนุกสนานกับการฉลองครั้งยิ่งใหญ่ ในฐานะศูนย์กลางอารยธรรมของแอสตรา สมควรแล้วที่ลูโมโพลิสจะมีวันแบบนี้บ้าง แต่ทุกวันย่อมมีจุดสิ้นสุด",
  str_loading_h_desc25 = "สำหรับชาวนอร์ธแลนด์ ดินแดนแห่งฤดูหนาวที่ยาวนาน ป่าที่มีหิมะปกคลุมคือภาพที่คุ้นตา เวลาที่แสงแรกในยามเช้าส่องตามยอดไม้ที่เป็นน้ำแข็ง แสงอาทิตย์จะหักเหผ่านแท่งน้ำแข็งมากมายนับไม่ถ้วน เกิดเป็นลำแสงมากมายที่เปล่งประกายร่ายรำ จนบัดนี้ได้กลายเป็นสัญลักษณ์แห่งความศรัทธาของทุกคนที่เรียกดินแดนแห่งนี้ว่าบ้าน",
  str_loading_h_desc26 = "หลายคนอ้างว่าทะเลสาบแห่งนี้เกิดขึ้นจากธารน้ำแข็งที่ละลายเมื่อนานมาแล้ว แต่ไม่มีใครอธิบายได้ว่าเหตุใดทะเลสาบที่ลึกและนิ่งสงบราวกับกระจกนี้จึงไม่เป็นน้ำแข็งเลยตลอดทั้งปี นี่คือสาเหตุที่หลายคนเชื่อว่ารูปลักษณ์ที่ปรากฎของทะเลสาบกระจกเงานี้เป็นของขวัญจากสวรรค์ ลือกันว่าตอนที่ราชวงศ์นอร์ธแลนด์มาเยือนที่นี่ พวกเขาได้เห็นนิมิต อีกทั้งดอกนาร์ซิสซัสที่เบ่งบานอยู่รอบทะเลสาบกระจกเงาก็ยิ่งทำให้น่าพิศวงเข้าไปใหญ่",
  str_loading_h_desc27 = "บางคนบอกว่าแสงแรกที่โผล่พ้นขอบฟ้านอร์ธแลนด์คือสิ่งที่คอยปกป้องดินแดนแห่งนี้ โดยขับไล่การรุกรานของความมืดมิดให้หมดไปจากดินแดนแห่งรัตติกาลนิรันดร์ อย่างไรก็ดี ตำนานอื่น ๆ กล่าวว่าพลังที่แท้จริงของนอร์ธแลนด์นั้นอยู่ที่ความมุ่งมั่นในการปกป้องดินแดนแห่งนี้ที่ไม่จางหาย... ความมุ่งมั่นที่สว่างไสวยิ่งกว่าออโรราที่สุกสกาว และรุ่งอรุณที่เปล่งประกาย ซึ่งจะคงอยู่เช่นนี้ตลอดไปและคงความยิ่งใหญ่ตลอดกาล",
  str_loading_h_desc28 = "ซากปรักหักพังทั้งหมดอยู่ห่างไกลจากโลกโดยสิ้นเชิงและเต็มไปด้วยอาคารที่ไม่เคยเห็นมาก่อน\nดูเหมือนว่าจะไม่มีร่องรอยของชนเผ่าพื้นเมืองเลย",
  str_loading_h_desc29 = "ซากปรักหักพังเกิดพังทลายลงมาอย่างรวดเร็วโดยไม่ทราบสาเหตุ\nทั้งเครื่องจักรที่กำลังซ่อมแซมซากปรักหักพังกับพวกอิคลิพไซท์ที่อาศัยอยู่ข้างในต่างก็พากันแตกตื่น",
  str_loading_h_desc30 = "มีความลับอีกมากมายที่ยังคงไขไม่กระจ่างในเมืองนี้\nหรือว่าทุกคนจะมีคำตอบในใจอยู่แล้วนะ...",
  str_loading_h_desc31 = "แกนพลังงานนี้ดำเนินการมานานเกินกว่าจะบอกระยะเวลาได้ มันดิ้นรนเหมือนผู้ป่วยที่กำลังจะตาย การเต้นของหัวใจแต่ละครั้งอาจเป็นครั้งสุดท้าย",
  str_loading_h_desc32 = "ศูนย์ข้อมูลของแอ๊บบี้ โมดูลชีววิทยาที่บ้าคลั่งนี้ผลิตและพัฒนาอิคลิพไซท์อย่างต่อเนื่อง เสียงกรีดร้องที่โกรธเกรี้ยวและน่าสะพรึงกลัวของพวกมันเป็นที่หวาดผวาไปทั้งศูนย์",
  str_loading_h_desc33 = "เกาะเล็ก ๆ ทางตะวันออกของแอสตราที่อุดมไปด้วยทรัพยากรและแทบจะไม่มีอิคลิพไซท์ ร้อยปีก่อน เมืองโคฟุโจได้ก่อตั้งขึ้นที่ใจกลางเกาะเมฆาและเกาะหลักได้ส่งโชกุนมาปกครองที่แห่งนี้ ตั้งแต่นั้นมาเกาะทั้งสองก็เกิดความขัดแย้งกัน เบื้องหลังของอดีตที่ชาวเกาะเมฆาหวาดกลัวนั้น โชกุนผู้นี้กำลังจะนำความลับของเขาและเกาะเมฆาไปสู่อนาคตที่มิอาจคาดเดา...",
  str_loading_h_desc34 = "เทศกาลคาสึกะที่เป็นประเพณีของเกาะเมฆาได้รับการอนุรักษ์ไว้ตามกาลเวลาที่ล่วงเลยไป เมื่อเวลาเปลี่ยน ผู้คนก็เกิดขึ้นและดับไป แต่ดอกซากุระที่บานสะพรั่งจะคงอยู่เช่นนั้นดั่งเดิม",
  str_loading_h_desc35 = "เทศกาลท่องราตรีเป็นงานพิเศษในโคฟุโจ ซึ่งจัดขึ้นเพื่อระลึกถึงวิญญาณผู้ล่วงลับ\nเมื่อถึงฤดูกาลที่ดอกซากุระบาน ชาวเมืองจะจัดงานเทศกาลคาสึกะประจำปี\nทุกคนจะแต่งตัวและใส่หน้ากากแมว เดินถือตะเกียงไปตามถนนในเวลากลางคืน\nเป็นความเชื่อว่าพวกเขาจะเชื่อมต่อกับโลกหลังความตายได้ด้วยวิธีนี้และได้พบกับ\nคนรักที่เสียชีวิตไปแล้วอีกครั้งหนึ่ง",
  str_loading_h_desc36 = "โคฟุโจตั้งอยู่บนยอดสูงสุดของเกาะเมฆา เมื่อผู้คนจากส่วนอื่นของเกาะแหงนมองขึ้นไป จะคล้ายกับว่าเมืองนั้นอยู่ในม่านเมฆ บังเกิดความลึกลับและเคร่งขรึมยิ่งนัก บรรพบุรุษของเกาะเมฆาค่อย ๆ ก่ออิฐสร้างโคฟุโจขึ้นด้วยความอุตสาหะในอดีตที่เนิ่นนาน แต่วันนี้ไฟที่โหมกระหน่ำได้เผาผลาญทุกอย่างให้มอดเป็นจุล พาให้ผู้คนเริ่มตรึกตรองถึงสิ่งที่พวกเขาต้องการอย่างแท้จริง มีใครบ้างที่ยินดีในสงคราม และมีผู้คนมากมายเพียงใดที่ต้องชีพวายในเปลวเพลิง",
  str_loading_h_desc37 = "ภูตผีก่อตัวขึ้นในช่วงเวลาของหยิน กลายเป็นสนามพลังที่หลอกหลอนเกาะเมฆา ในขณะที่อาวุธศักดิ์สิทธิ์ก็ได้ก่อรูปร่างขึ้นในช่วงเวลาของหยาง เปี่ยมไปด้วยพลังหยางที่บริสุทธิ์สามารถกำจัดวิญญาณชั่วร้ายได้หมดสิ้น อย่างไรก็ตาม เมื่อหยินและหยางอยู่ในมือของคนโลภและเห็นแก่ตัว ความปรารถนาที่ไม่อาจควบคุมได้ก็เปลี่ยนไปเป็นสิ่งที่น่ากลัวยิ่งกว่าผี",
  str_loading_h_desc38 = "ตั้งอยู่ทางตอนใต้ของทะเลทรายเรดีเซล มีลมพัดแรงไม่หยุดปกคลุมอยู่โดยรอบ ภายในหมอกสีเหลืองที่แผดเผาไกลสุดลูกหูลูกตา และถูกคั่นแซมด้วยกระดูกสีขาวโพลนกับต้นไม้ที่ตายแล้วชนิดมองไม่เห็นสีเขียว แต่ทว่าแม้จะอยู่ในที่ที่รกร้างและน่าสยดสยองถึงเพียงนี้ แต่ก็ยังมีสัญญาณของสิ่งมีชีวิตให้เห็นอยู่ นอกจากแมงป่องไฟลุกและงูหัวแหวนแดงฉานที่ซ่อนตัวอยู่ในเงาโขดหินแล้ว ยังมีผู้ล่าที่ตัวใหญ่กว่าแอบซุ่มอยู่ในทะเลทราย ที่นี่ใครอ่อนแอจะต้องกลายเป็นเหยื่อที่ถูกขย้ำในที่สุด",
  str_loading_h_desc39 = "แผ่นดินรอบภูเขาไฟถูกปกคลุมไปด้วยหินทรายหยาบสีดำ เมื่อมองขึ้นไป จะเห็นลาวาที่แผดเผาไหลย้อยมาตามรอยแยกของภูเขา จนก่อตัวเป็นน้ำตกลาวาที่งดงามที่ริมหุบเขา ยิ่งได้เข้าใกล้ภูเขาไฟมากขึ้นเท่าใด อากาศก็ยิ่งร้อนขึ้นเท่านั้น จนแทบจะหายใจไม่ได้ สิ่งที่น่าทึ่งไปกว่านั้นก็คือ หินทรายขนาดเล็กหน่อยสามารถลอยอยู่ในอากาศได้ด้วยแรงกำลังที่คาดไม่ถึง",
  str_loading_h_desc40 = "หุบเขาเขี้ยวเพลิงลุกโชนที่อยู่ใกล้ขอบรัตติกาลนิรันดร์ ได้ชื่อนี้มาจากภูมิประเทศที่เว้าแหว่งของมัน มีความลาดชันที่เกือบจะทิ้งดิ่งลงสู่พื้นดิน และแม่น้ำที่แห้งเหือดไปนานแล้วภายใต้พระอาทิตย์ที่แผดเผา ก็มีความคดเคี้ยวและแตกระแหงในหลายจุดจนแทบจะเรียกไม่ได้ว่าเป็นถนน แต่บางทีสิ่งเหล่านี้ที่ดูเหมือนเป็นอุปสรรคที่ก้าวข้ามไปไม่ได้ กลับถูกกำหนดให้เป็นเส้นทางแรลลี่ครั้งแรกของเรดีเซล เวรนช์...",
  str_loading_h_desc41 = "ในการซ่อนห้อง ให้ใช้อิฐและกระเบื้องปิดประตู และใช้ทรายกับโคลนอุดหน้าต่างเอาไว้ เปลี่ยนมันให้กลายเป็นส่วนหนึ่งของถนนหรือกำแพงที่ไม่มีความสำคัญ และลบมันออกจากแผนที่ตลอดไป มุมหนึ่งของโลกนี้ได้หายไปแล้วแต่ไม่มีผู้ใดล่วงรู้ มันได้รับการเก็บรักษาไว้เพื่อทรู ออเดอร์โดยเฉพาะ ลูโมโพลิสมีขนาดใหญ่มาก และซอกหลืบเล็ก ๆ แบบนี้ก็ผ่านตาไปได้โดยที่ไม่มีใครสังเกตเห็น",
  str_loading_h_desc42 = "เมื่อยืนอยู่หลังม่านหนาก่อนเริ่มการแสดง คุณต้องควบคุมหัวใจที่เต้นแรงให้ได้ เพราะด่านนี้ไม่อนุญาตให้ใครหยุดเมื่อเปิดม่านแล้ว คำตอบของการแสดงที่สมบูรณ์แบบอยู่ที่ความพยายามครั้งต่อไปของคุณ",
  str_loading_h_desc43 = "ใคร ๆ ก็รู้ว่าหุ่นเชิดไม่มีชีวิตและจิตใจ แต่เมื่อมันถูกจัดวางท่าทางให้เหมือนกับมีชีวิต บางคนอาจคิดว่ามันเหมือนมนุษย์มากกว่าคนที่มีชีวิตอยู่จริง ๆ ก็ได้ บางที เราอาจคาดหวังให้บางสิ่งในตัวเรานั้นมีจิตวิญญาณเช่นกัน",
  str_loading_h_desc44 = "ถ้าจะมีอะไรสักอย่างที่เป็นตัวแทนของอีราเวล ก็ต้องเป็นแดนดิไลออนนี่แหละ ดอกไม้สีขาวฟูฟ่องเหล่านี้พบได้ทั่วไปในดินแดนอีราเวล และเพียงแค่สายลมพัดผ่านเท่านั้นก็จะเกิดเป็นภาพลวงตาราวกับว่ามีหิมะตก บางคนไม่ชอบแดนดิไลออนเพราะพวกเขารู้สึกว่าดอกไม้ชนิดนี้ไม่ได้ให้ความรู้สึกของการเฉลิมฉลองเทศกาล เพราะไม่ว่ามันไปตกที่ไหนก็จะงอกรากลงดินที่จุดนั้น แต่ในอีราเวลคุณจะพบว่า ไม่ว่าลมจะพัดไปในทิศทางใดก็จะมีแดนดิไลออนขนาดใหญ่บินไปบินมาเสมอ พวกมันไปมาพร้อมกับสายลม แต่ยังคงอยู่ในดินแดนแห่งนี้เสมอมา",
  str_loading_h_desc45 = "อีราเวลเป็นสถานที่ที่สงบเยือกเย็น สายลมที่นี่มีความนุ่มนวลเสมอ ทัศนีภาพที่นี่ก็เขียวขจีเสมอ และอากาศที่นี่ก็สดชื่นเสมอ แม้กระนั้นในที่สุดอะไร ๆ ก็กลับกลายเป็นน่าเบื่อเมื่อเวลาผ่านไปนาน ๆ และทำให้รู้สึกได้ถึงความว่างเปล่าอยู่ลึก ๆ ราวกับว่ามีอะไรบางอย่างที่ขาดหายไปในธรรมชาติอันกว้างใหญ่นี้ ที่ซึ่งมีไก่โต้งขันรับอรุณและกลุ่มหมอกควันเต้นรำในเวลาย่ำค่ำ",
  str_loading_h_desc46 = "ตามคำแนะนำ คุณกลับไปที่อีราเวล สถานที่ซึ่งเปี่ยมไปด้วยความทรงจำที่คุ้นเคย\nอย่างไรก็ตาม เบื้องล่างของอีราเวลนั้นมีความลับซ่อนอยู่\nความลับนี้เกี่ยวกับอีราเวล อดีตและอนาคต และเกี่ยวกับคุณ",
  str_loading_h_desc47 = "ในพื้นที่กว้างใหญ่ใต้หอคอยสีขาวมีทางเข้าที่นำไปสู่ใต้ดินซ่อนอยู่!\nคุณอาจเป็นคนแรกที่ไขกุญแจเปิดที่นี่อีกครั้งหลังจากผ่านมาหลายพันปี\nสำรวจซากปรักหักพังที่ลึกลงไปใต้ดิน... และที่นั่น คุณอาจพบสิ่งที่ตามหามานานแสนนาน",
  str_loading_h_desc48 = "อุปกรณ์รูปทรงวงแหวนลึกลับที่อยู่ใจกลาง \"ฐานซ่อมบำรุงโคลอสซัส\" ในใต้ดินของอีราเวล ดูเหมือนว่าจะเป็นศูนย์ควบคุมของฐานทั้งหมดที่ทำให้องค์ประกอบอันกว้างใหญ่ทำงานมาโดยตลอด\nแต่จะว่าไปแล้ว มันดูเหมือนไม่ได้รับการดูแลมานาน และไม่รู้ว่ายังใช้งานได้อยู่หรือไม่...",
  str_loading_h_desc49 = "เหตุที่หอคอยสีขาวตั้งอยู่ในอีราเวลนั้นเป็นความลับในตัวมันเอง\nหอคอยสีขาวที่ตั้งตระหง่านสะท้อนถึงเทคโนโลยีโบราณที่ยังคงมีอยู่ในปัจจุบัน เสียงสะท้อนนี้จะหมายถึงภัยคุกคามจากอดีตหรือความหวังสำหรับอนาคตกันแน่นะ?",
  str_loading_h_desc50 = "อุปกรณ์ลึกลับในฐานใต้ดินของอีราเวลดูเหมือนจะมีพลังในการแปรเปลี่ยนออโรเรียน ความรู้เกี่ยวกับวิธีการใช้งานได้หายไปแล้ว ไม่มีใครรู้ว่ามันทำอะไรได้จริง ๆ หากจะใช้งานก็ต้องคำนึงถึงความเสี่ยงที่อาจเกิดขึ้นด้วย...",
  str_loading_h_desc51 = "คุณกลับมาที่นี่เพื่อใช้ \"คอร์ดแห่งบัญญัติ\"\nแม้ว่าเส้นทางนี้อาจยากเย็นเกินไปสำหรับชาวเคเลสไทต์ แต่แม้แต่ความหวังเล็กน้อยก็คุ้มค่าที่จะยึดถือไว้",
  str_loading_h_desc52 = "บรรยากาศที่กลมกลืนและภูมิทัศน์แบบธรรมชาติ... สำหรับเคเลสไทต์ ไม่มีมรดกใดที่ดีไปกว่าสวนลอยฟ้าอีกแล้ว ที่ลานหอคอยสีขาวอันกว้างใหญ่นี้ยังมีอะไรต้องจัดการอีกมาก เรื่องสัพเพเหระที่คุณทำจะกลายเป็นอนาคตส่วนหนึ่งของเคเลสไทต์",
  str_loading_h_desc53 = "น้ำพุแห่งความหวังหน้าหอคอยไฮยาซินท์คือหัวใจของสวนลอยฟ้า คุณสามารถพูดคุยกับเพื่อนฝูง ปล่อยปลาที่จับมาได้ลงในบ่อ หรือโยนเหรียญแห่งความหวังที่แวววาวลงไปในบ่อเพื่อขอพรอันเจิดจรัสก็ได้",
  str_loading_h_desc54 = "ห้องที่มีมากที่สุดในสวนลอยฟ้า มีแสงสว่างทั่วถึงและระบายอากาศได้ดี เหมาะแก่การเป็นพื้นที่นั่งเล่นหรือเก็บของได้ยอดเยี่ยม แต่อย่าลืมทำความสะอาดให้ดีก่อนใช้งานนะ",
  str_loading_h_desc55 = "ภายใต้ผ้านวมที่ปูไว้เรียบร้อยมีเสื้อผ้าสกปรกที่ไม่ได้ซักมาเป็นสัปดาห์แล้ว ตู้แน่นเอียดก็เต็มไปด้วยถ้วยแก้วที่พร้อมจะหล่นลงมาทุกเมื่อ มีขนมกรุบกรอบเคี้ยวเพลินที่กินไม่หมด หนังสือ และนิตยสารกระจัดกระจายอยู่ทุกที่... นี่เป็นเรื่องปกติของห้องเด็กผู้ชายใช่ไหม?",
  str_loading_h_desc56 = "\"ไม่มีตระกูลใดที่อยู่ยงคงกระพัน ผลประโยชน์เท่านั้นที่จีรังยั่งยืน\" เช่นเดียวกับตระกูลเก่าแก่จำนวนมากในอัมบราตัน อิฐและกระเบื้องทุกชิ้นที่ก่อร่างเป็นตระกูลแอนเดอร์เซนนั้น ก็ล้วนอาศัยอิทธิพลและผลประโยชน์มหาศาล แต่ท่าทางเคานท์แอนเดอร์เซนคนปัจจุบันจะชอบลงทุนแบบอื่น",
  str_loading_h_desc57 = "ทำให้แขกของตระกูลรู้สึกเหมือนอยู่บ้าน และทำให้ศัตรูเกิดความรู้สึกเกรงกลัว คำสั่งของเจ้านายต้องลุล่วงไม่ว่าจะด้วยวิธีใดก็ตาม อย่างไรก็ดี คุณสมบัติของพ่อบ้านและนายท่านนั้นเท่าเทียมกัน พ่อบ้านอันดับหนึ่งของตระกูลแอนเดอร์เซนเป็นคนที่สมบูรณ์แบบ แม้กระทั่งในเวลาที่เขาทดสอบเจ้านายตนเองก็ไม่มีวันออมมือ",
  str_loading_h_desc58 = "ปกติจะพบสัตว์มหัศจรรย์อยู่ห่างจากผู้คน อาศัยอยู่อย่างอิสระในภูเขา ป่าไม้ ถิ่นทุรกันดาร ทุ่งหิมะ หรือมหาสมุทรลึก พวกมันสามารถใช้ลูมิน่าได้และมีความสามารถหรือลักษณะเฉพาะตัวที่แตกต่างจากสัตว์ทั่วไป สิ่งมีชีวิตที่เป็นมิตรเหล่านี้ไม่ค่อยมีปฏิสัมพันธ์กับชาวออโรเรียน แต่พวกมันมักจะยื่นมือช่วยเหลือเมื่อเผชิญกับวิกฤต\nอย่างไรก็ตาม ในเวลาเดียวกัน การเปลี่ยนแปลงที่อยู่อาศัยของพวกมันและความบกพร่องทางการสืบพันธุ์ของพวกมันเองทำให้จำนวนประชากรโดยรวมลดลง และสัตว์มหัศจรรย์จำนวนมากกำลังใกล้สูญพันธุ์",
  str_loading_h_desc59 = "ที่ใดมีสัตว์มหัศจรรย์ ย่อมต้องมีนักสัตว์มหัศจรรย์วิทยาในบริเวณใกล้เคียง แม้พวกเขาจะหาตัวยากยิ่งกว่าสัตว์มหัศจรรย์ แต่กลุ่มคนเหล่านี้มีความรักให้กับสรรพสัตว์อย่างล้นเหลือ พวกเขาจะตามรอยสัตว์มหัศจรรย์ไปจนสุดขอบโลกเพื่อบันทึกรายละเอียดระบบนิเวศและอุปนิสัยของสัตว์มหัศจรรย์ แล้วจัดทำเป็นหนังสือเพื่อเป็นมรดกแก่คนรุ่นหลังต่อไป นอกจากนี้พวกเขายังช่วยเหลือสัตว์มหัศจรรย์ในยามเผชิญหน้ากับอันตรายอีกด้วย\nฟีญ่ากำลังอยู่บนเส้นทางไปสู่การเป็นนักสัตว์มหัศจรรย์วิทยา โดยทุ่มเทความพยายามอย่าง \"แน่วแน่และจริงจัง\"",
  str_loading_h_desc60 = "ที่อยู่ของคณะละครสัตว์นักมายากลและผู้เฒ่าบิลล์นั้นไม่แน่ไม่นอน เมื่อไม่นานนี้มีข่าวลือว่าพวกเขาได้รับเชิญไปยังเมืองท่าแห่งหนึ่งที่มีชื่อว่าเมืองฮาร์เบอร์ หัวหน้าคณะละครสัตว์ที่ชื่อว่าเจโน่เป็นคนนิสัยแปลก ๆ และลูกน้องของเขาก็ล้วนแต่มีทักษะเฉพาะตัว เขาจะมอบงานฉลองเทศกาลฤดูร้อนที่ยอดเยี่ยมและน่าจดจำให้กับประชาชนในพื้นที่",
  str_loading_h_desc61 = "เจ้าเมืองฮาร์เบอร์ท่าทางหมกมุ่นกับเรือมรกตเป็นอย่างมาก มีอะไรอยู่ที่นั่นนะ? มีความลับอะไรซ่อนอยู่บ้าง? อีกไม่นานกิจกรรมที่เสียงดังอื้ออึงก็จะเสร็จสิ้นไป และกระแสน้ำใต้ท่าเรือที่นิ่งสงบก็จะกระเพื่อมขึ้นมาเป็นระลอก...",
  str_loading_h_desc62 = "หลังจากจับเอลวิสได้แล้ว ความวุ่นวายที่เขาก่อขึ้นก็ดูเหมือนจะสิ้นสุดลง แต่ไม่มีใครรู้จุดประสงค์ที่แท้จริงของเขา ความสงสัยในใจคาร์ลีนทำให้เธอนั้นเศร้าหมองไม่ต่างจากสภาพอากาศของเมืองฮาร์เบอร์ เมื่อไรความจริงจะปรากฎนะ? คาร์ลีนและพรรคพวกของเธอจึงอยู่ที่เมืองฮาร์เบอร์เพื่อสืบความจริงให้กระจ่าง แม้กระนั้น ดูเหมือนว่าเอลวิสจะยังไม่ล้มเลิกความตั้งใจของเขา",
  str_loading_h_desc63 = "ผนึกโบราณถูกสั่นคลอน ปลุกอิคลิพไซท์ในตำนานที่หลับใหลอยู่ใต้ทะเลลึก สงครามที่ชายฝั่งกำลังจะปะทุขึ้นในขณะที่คลื่นซัดเข้าหาเมืองฮาร์เบอร์ ในการเผชิญหน้ากับอิคลิพไซท์ ผองเพื่อนจะปกป้องเมืองฮาร์เบอร์ไว้ได้หรือไม่? เอลวิสจะหาทางแก้ไขวิกฤตนี้ได้หรือไม่?",
  str_loading_h_desc64 = "วาฬเมฆาสลายพลังความมืดที่แผ่ซ่านอยู่ในอากาศและตัดสะบั้นเมฆดำที่ปกคลุมเมืองฮาร์เบอร์ และเมื่อแสงแดดส่องลงมาที่เมืองฮาร์เบอร์ ดูเหมือนว่าทุกอย่างจะเปลี่ยนไปในทางที่ดีขึ้น แม้แต่ลมที่พัดหวีดหวิวก็มีทีท่าว่าจะสงบลง",
  str_loading_h_desc65 = "สุริยุปราคาบุกเมื่อ 12 ปีที่แล้ว\nหลังจากการต่อสู้ที่ดุเดือดนับไม่ถ้วน นี่คือสิ่งที่หลงเหลืออยู่ใน Euphoria\nแผลที่ไม่มีวันหาย ค่อยๆ เปื่อย",
  str_loading_h_desc66 = "เมืองนี้เต็มไปด้วยความบาปมากมายจากอดีต\nพวกเขาเติบโตเหมือนเนื้องอกในร่างกาย และต้องถูกลบออกเพื่อให้ฟื้นตัว\nบางทีแสงแดดก็จะกลับมาที่แห่งนี้",
  str_loading_h_desc67 = "—นี่คือวิธีที่โฆษณาในหนังสือพิมพ์ อาคารหลังนี้ในเขตชานเมือง Umbraton มีเจ้าของนับไม่ถ้วนตลอดหลายปีที่ผ่านมา เพิ่งเข้ามาอยู่ในครอบครองของ Andersens ซึ่งทำให้เป็นบ้านผีสิงอย่างที่เป็นอยู่ในปัจจุบัน สันนิษฐานว่าสร้างขึ้นโดยสถาปนิกนอกรีตที่เป็นผู้บงการเบื้องหลังการออกแบบบันไดปลอม ประตูและหน้าต่างที่วางผิดที่ โคมไฟระย้าและภาพวาดที่แปลกประหลาดทั้งหมดเป็นการออกแบบของเขาเอง",
  str_loading_h_desc68 = "ห้องใต้ดินแปลกตาอยู่ใต้สิ่งที่เรียกว่าบ้านผีสิง Andersen ฉันรู้ว่าคุณไม่เคยเห็นมันสำหรับตัวคุณเอง เป็นไปได้ว่าแม้แต่เจ้าของปัจจุบันก็ไม่เคยสนใจมันเลย เจ้าของบ้านคนสุดท้ายก้าวเข้ามาที่นั่นเพียงครั้งเดียวและขายที่นั้นหลังจากนั้นไม่นานก่อนจะย้ายไปไกลแสนไกล มีข่าวลือมากมายรอบๆ ห้องใต้ดิน แต่ฉันไม่เชื่อแม้แต่คนเดียว ท้ายที่สุดแล้ว คนเป็นไม่มีทางรู้ความจริง",
  str_loading_h_desc69 = "ศูนย์วิจัยอิลลูมินาเป็นศูนย์กลางวิทยาศาสตร์และเทคโนโลยีของสมาพันธ์อิลลูมินา\nนักวิจัยที่นี่มีหน้าที่รับผิดชอบในการวิเคราะห์อุปกรณ์เทคโนโลยีโบราณและคิดค้นเทคโนโลยีใหม่ๆ\nอย่างไรก็ตาม การวิจัยไม่มีที่สิ้นสุด คุณจะพบข้อมูลที่คุณต้องการที่นี่?",
  str_loading_h_desc70 = "เครื่องจำลองสนามรบที่สร้างขึ้นโดย Illumina Research Center จะนำคุณเข้าสู่การต่อสู้ใดๆ ที่บันทึกไว้ในระบบของมัน\nอย่าสงสัยในความถูกต้องของฉากที่มันเสกให้คุณ: ทหารที่สิ้นหวัง สุริยุปราคาอันดุร้าย ดวงอาทิตย์ที่ถูกบดบังด้วยเปลวเพลิงแห่งสงคราม.... ทุกสิ่งที่คุณเห็นที่นี่เกิดขึ้นจริง",
  str_loading_h_desc71 = "ตัวเลขและวิทยาศาสตร์เป็นสิ่งที่เข้าใจไม่ได้และห่างไกล สิ่งที่แปลกคือพวกเขาอาจแสดงอารมณ์และความตั้งใจอย่างกะทันหันต่อหน้าเราอย่างแม่นยำอย่างหาที่เปรียบมิได้ ระยะทางบางระยะทางน่ากลัวยิ่งขึ้นเมื่อวัดได้",
  str_loading_h_desc72 = "สถานที่ที่ดวงอาทิตย์ของ Lumopolis ไม่ส่องแสง นอกแนวป้องกันของ Undercities ของ Illumina เมืองนี้เป็นสถานที่สุดท้ายที่ชาวออโรเรียนมารวมตัวกัน โดยไม่คำนึงถึงสถานะและความแตกต่างทางชาติพันธุ์ ผู้อยู่อาศัยที่นี่รวมเป็นหนึ่งเดียวเพื่อต่อต้านศัตรูเพื่อปกป้องวัฒนธรรมที่ซ่อนอยู่ในเมืองเล็กๆ แห่งนี้",
  str_loading_h_desc73 = "อัศวินแห่งดินแดนชายแดนเหล่านี้แตกต่างจากในลูโมโปลิส พวกเขากลิ้งไปมาในสนามรบมากจนทรายเปื้อนผ้าไหมสีขาวที่พวกเขาสวมใส่เป็นสีที่แตกต่างจาก Lumopolis พวกเขาคุ้นเคยกับการเดินตามคมดาบมากกว่าการคุกเข่าสู่มงกุฎ",
  str_loading_h_desc74 = "ยักษ์ใหญ่ที่ชนที่นี่มีขนาดใหญ่มาก\nครั้งหนึ่งมันบินได้อย่างอิสระด้วยปีกที่สามารถปกคลุมท้องฟ้าได้\nแต่ตอนนี้มันมองไปทาง Eraveil โชคชะตาจะไม่กลับไปที่นั่นอีก",
  str_loading_h_desc75 = "ยักษ์ใหญ่ที่ติดตั้งจอยักษ์และอุปกรณ์เสียงจากบนลงล่าง\nนักโบราณคดีอ้างว่าเมื่อเฉลิมฉลองเทศกาลของพวกเขา ชาว Caelestites จะบิน Eulogoz ขึ้นไปบนท้องฟ้าและถ่ายทอดเพลงเฉลิมฉลองและภาพการเต้นรำไปทั่ว Eraveil\nอย่างไรก็ตาม จากข้อมูลที่เหลืออยู่ Eulogoz และผู้นำทางได้หายตัวไปพร้อมกันอย่างลึกลับเมื่อประมาณหนึ่งร้อยปีที่แล้ว",
  str_loading_h_desc76 = "สัตว์มหัศจรรย์ที่สามารถมีชีวิตอยู่ได้ตลอดไป\nมีข้อมูลทางประวัติศาสตร์เกี่ยวกับโอโรโบรอสน้อยมาก และนักสัตววิทยาหลายคนเชื่อว่าโอโรโบรอสเป็นเพียงสิ่งประดิษฐ์เท่านั้น\nอย่างไรก็ตาม Vic เชื่อมั่นว่ามันมีอยู่จริงและเชื่อว่ามีความเชื่อมโยงที่อธิบายไม่ได้ระหว่างตัวเขากับสัตว์ร้ายตัวนี้",
  str_loading_h_desc77 = "Ouroboros ภายในไข่ของมันสามารถถักทอความฝันได้ตามใจของมันเอง และทำให้ความฝันเป็นวงจรต่อเนื่องไปจนกว่ามันจะผ่านระยะฟักตัวที่ยาวนานอย่างปลอดภัย\nในอดีต ผู้คนที่มีแรงจูงใจแอบแฝงได้จงใจบุกเข้าไปในความฝันของ Ouroboros เพื่อพยายามหยุดยั้งไม่ให้ฟักตัวออกมา เพื่อที่พวกเขาจะได้มีชีวิตนิรันดร์ในความฝัน แต่พวกเขากลับล้มเหลวโดยไม่มีข้อยกเว้น\nนั่นเป็นเหตุผลที่คุณควรคิดให้รอบคอบก่อนที่จะเข้าสู่ความฝันของ Ouroboros",
  str_loading_h_desc78 = "Shadowind จอดเรือที่ Twin Pavilions Bay และนำข่าวดีมาสู่ชาวพื้นเมือง Longzhou ที่อาศัยอยู่ที่นั่น เส้นทางที่เรือ Shadowind แล่นเชื่อมระหว่าง Longzhou และ Astra และกลายเป็นเส้นทางสายสำคัญสำหรับการแลกเปลี่ยนวัฒนธรรมและการค้าระหว่างสองภูมิภาค เรือเหล่านี้เดินทางไปมา บรรทุกสินค้าที่เป็นเอกลักษณ์ อาหารอันโอชะ และสมบัติล้ำค่าของหลงโจว และมอบเส้นทางกลับบ้านที่ตามหามานานสำหรับผู้ที่ติดอยู่ห่างไกลจากบ้าน",
  str_loading_h_desc79 = "ทะเลไม่ยอมจำนนเมื่อต้องเผชิญหน้ากับกองทัพที่เตรียมพร้อมมาอย่างดี และมันก็ไม่แสดงความเมตตาต่อปลาที่กระพือหาง เมื่อเกิดพายุ คุณเพียงแค่สัมผัสประสบการณ์การดำรงอยู่ไม่รู้จบของมันในช่วงเวลาเดียว เมื่ออยู่ในใจกลางของพายุ กะลาสีมักจะอธิษฐานต่อพญานาค โดยปรารถนาให้ประสบกับชะตากรรมที่คล้ายคลึงกัน ให้ดำดิ่งสู่ความลึกของมหาสมุทรอย่างไม่เกรงกลัว จากนั้นจึงเคลื่อนตัวไปยังบริเวณน้ำตื้นของบ้านเกิดอย่างปลอดภัย",
  str_loading_h_desc80 = "เรือที่จมอยู่บนพื้นมหาสมุทรอย่างเงียบ ๆ ในเวลานี้เงียบสงบกว่าครั้งใด ๆ ที่ลอยอยู่บนคลื่น ทะเลกลืนเสียงทั้งหมด กลบเสียงร้องขอชีวิต และทิ้งไว้เพียงภาพแห่งจุดจบ—ภาพถ่ายสีซีดจางถูกพัดมาเกยฝั่ง ทะเลนั้นไร้ขอบเขต อาจมีสุสานเรือมากมายเช่นนี้ แต่ไม่มีใครจ่ายส่วยให้หลุมฝังศพเหล่านั้น นั่นคือเสียงร้องที่ชาวโลกคิดถึง",
  str_loading_h_desc81 = "การไปถึงระดับของเขาและตัดสินสิ่งที่เขาทำหรือไม่ทำนั้นเป็นเรื่องไร้สาระ เขาไม่จำเป็นต้องอธิบายอะไรให้ใครฟัง ดังนั้นปัญหาทั้งหมดของเขาจึงเป็นของเขาคนเดียว และทัศนคติของเขาก็สำคัญ เขาไม่รู้สึกเสียใจ กลับเป็นสิ่งที่ใจดำกว่า—ความรู้สึกผิด การใช้คนคนเดียวเพื่อลบล้างบาปของคนเป็นร้อย... ความผิดของเขามาโดยเขาเองไม่ได้เลือก แต่ก็ทำให้เขามีความสงบในมโนธรรม",
  str_loading_h_desc82 = "เมื่อพูดถึงการฉลองวัน Mooncrown มีประเพณีที่แตกต่างกันไปทั่วทั้งทวีป\nในอิลลูมินา พวกเขาค่อนข้างเรียบง่ายและจริงจัง พวกเขาแสดงความรักด้วยการมอบซินนามอนโรลให้กับคู่รัก\nใน Lumopolis พวกเขาให้ความสำคัญกับพิธีการมากขึ้น และมอบโคลเวอร์สีแดงล้ำค่าให้กันและกันเพื่อแสดงถึงความจริงใจ\nในนอร์ธแลนด์ พวกเขาเฉลิมฉลองอย่างเรียบง่ายโดยมอบขวดเล็กๆ ที่เต็มไปด้วยน้ำจากทะเลสาบมิเรอร์เป็นของที่ระลึก ซึ่งเป็นตัวแทนของความรักอันบริสุทธิ์",
  str_loading_h_desc83 = "ตาข่ายดักฝันที่ถักทออย่างพิถีพิถัน จี้บุษราคัมอันวิจิตร พรมที่ครั้งหนึ่งเคยเป็นของสะสมในหมู่คนชั้นสูง...\nรู้สึกราวกับว่าคุณกำลังเข้าไปในร้านขายของเก่าที่สวยงามแทนที่จะเป็นสำนักงาน Courier Union\nทุกอย่างที่นี่ดูเหมือนจะแสดงให้เห็นว่าเจ้าของห้องนี้มีรสนิยมที่ยอดเยี่ยม\nคนส่วนใหญ่ในทะเลทราย Rediesel เป็นคนประหยัดอย่างคลั่งไคล้ แต่ Jeriah ต้องการสิ่งที่ดีที่สุดในแง่ของคุณภาพชีวิตและมาตรฐานความงามเท่านั้น",
  str_loading_h_desc84 = "พื้นที่ตอนกลางของทะเลทราย Rediesel มีโอเอซิสประปราย เหมือนดวงดาวในกาแล็กซี่ทรายแดงอันกว้างใหญ่\nผืนน้ำอันมีค่าของทะเลทรายหล่อเลี้ยงชีวิตนับไม่ถ้วน แต่ก็ก่อให้เกิดความน่าสะพรึงกลัวที่คาดไม่ถึง ซึ่งหนึ่งในนั้นคือหนอนทรายที่มีชื่อเสียงที่สุด\nยักษ์เหล่านี้มักจะซุ่มอยู่ในทรายเพื่อรอพร้อมที่จะโจมตีทุกสิ่งที่ผ่านไป",
  str_loading_h_desc85 = "ตามประเพณีทั่วทั้งทวีป วันไหว้พระจันทร์เป็นวันสำหรับคู่รักในการแสดงความรู้สึกของพวกเขา ผู้คนจำนวนมากจึงจัดงานแต่งงานในวันนี้\nสำหรับขุนนางดั้งเดิม บริการจัดส่งส่งความสุขในงานแต่งงาน บางคนถึงกับใช้เงินจำนวนมากเพื่อเชิญผู้ส่งสารเหล่านี้ให้เข้าร่วม\nเพื่อยับยั้งพฤติกรรมประเภทนี้ซึ่งส่งผลกระทบอย่างรุนแรงต่อประสิทธิภาพการทำงานของผู้ให้บริการขนส่งของทวีป Courier Union ได้ส่งเสริมกิจกรรมอื่น ๆ เพื่อพยายามเลิกประเพณีนี้อย่างค่อยเป็นค่อยไป",
  str_loading_h_desc86 = "ภายใต้คำแนะนำของ Schwartz Hall of Justice ได้เปิดแผนกชั่วคราวเพื่อจัดการกับข้อพิพาทเกี่ยวกับความรักเมื่อเร็ว ๆ นี้ในช่วงเวลาพิเศษของปีเพื่อให้การพิจารณาคดีของศาลหลักมีความจริงจัง การเข้าสู่แผนกโรมานซ์เปรียบเสมือนการนั่งรถม้าที่ล้อจะไม่หยุดหมุน ก่อนที่ค้อนของผู้พิพากษาจะล้มลง ตรวจสอบให้แน่ใจว่าคุณได้นำหลักฐานที่สำคัญที่สุดมาเปิดเผย",
  str_loading_h_desc87 = "ความกระตือรือร้นในวัน Mooncrown ยังไม่ลดลงอย่างชัดเจนใน Lumopolis เนื่องจากกลุ่มผู้คลั่งไคล้ Mooncrown กำลังจัดร้านเสริมความงามอย่างกะทันหัน โดดเด่นด้วยการเปิดตัวบอลลูนลมร้อนรูปพระจันทร์ ทั้งสามัญชนและขุนนางต่างมารวมตัวกันใต้แสงจันทร์เพื่อเต้นรำ คลุกคลี และเพลิดเพลินกับเพลงสรรเสริญแห่งฤดูกาล นี่เป็นช่วงเวลาที่ความรู้สึกชั่วคราวและชั่วนิรันดร์สามารถเบ่งบานได้ในพริบตา",
  str_loading_h_desc88 = "ไม่มีใครใน Lumopolis ที่ไม่รู้จัก Stairway to the Skies ด้วยผู้คนที่ผ่านไปมาและเยี่ยมชมสถานที่นี้ ถนนนับไม่ถ้วนนำไปสู่บันไดสู่ท้องฟ้า คุณจะพบว่าตัวเองกำลังเดินบนเส้นทางสายใดสายหนึ่งเสมอ ในเมืองที่มีการแบ่งชั้นอย่างชัดเจน บันไดยาวนี้มีความหมายมากมายนอกเหนือจาก \"ทางเดิน\" ธรรมดาๆ เมื่อขึ้นบันไดเหล่านั้นเมื่อยังเป็นเด็ก เราสามารถมองเห็นดวงดาวได้ เมื่อโตเป็นผู้ใหญ่แล้ว ก็สามารถไปถึงสวนลุมโปลิสได้",
  str_loading_h_desc89 = "เรามาคิดกันใหม่ว่า \"ความยุติธรรม\" หมายถึงอะไร ไม่มีคำจำกัดความที่ชัดเจน โดยทั่วไป คนส่วนใหญ่เชื่อว่า \"ความยุติธรรม\" หมายถึงการทำสิ่งที่ถูกต้อง คนเหล่านี้เลือกตัวแทนที่จะพูดแทนพวกเขา และตัวแทนเหล่านี้รวบรวมความคิดเห็นของพวกเขาเป็นคะแนนเสียง คุณค้นพบผลลัพธ์ที่หลีกเลี่ยงไม่ได้ของระบบนี้แล้วหรือยัง? โครงสร้างของสังคมของเราถูกกำหนดให้นิยามคำว่า \"ความยุติธรรม\" จากจำนวนผู้ลงคะแนน ดังนั้นตอนนี้ฉันคือ \"ความยุติธรรม\"",
  str_loading_h_desc90 = "ตามคำสั่งของ Shadowlord สถานเลี้ยงเด็กกำพร้า Umbraton ได้ถูกสร้างใหม่บนสถานที่เดิม\nเช่นเดียวกับ Umbraton ในอดีต สถานเลี้ยงเด็กกำพร้าเก่าเป็นที่ซ่องสุมของการทุจริต ปราศจากความหวังที่ริบหรี่ที่สุด\nไฟเผาผลาญอดีตและดวงอาทิตย์ส่องแสงอย่างไม่เกรงกลัวต่อดินใหม่ที่อยู่ข้างใต้",
  str_loading_h_desc91 = "ฮาติเติบโตที่นี่กับแม่ของเธอ\nแม้ว่าเธอจะไม่ได้รับอนุญาตให้ออกไปข้างนอก แต่เธอก็มีความสุขในวัยเด็ก อาบด้วยความรักของแม่\nลูกม้าที่แม่ของเธอเย็บให้เธอเป็นเพื่อนเล่นเพียงคนเดียวของเธอเมื่อตอนเป็นเด็ก และหนังสือภาพสีสันสดใสของเธอคือขุมทรัพย์แห่งจินตนาการของเธอ\nแต่ตอนนี้ทุกอย่างหายไป",
  str_loading_h_desc92 = "Undercity ครั้งหนึ่งไม่ได้จดทะเบียนและไม่มีชื่อ แต่มันถูกยึดครองและสร้างใหม่โดยใครบางคนเมื่อหลายปีก่อน\nต่อมาเปลี่ยนชื่อเป็น \"Undercity X\" และ \"Institute X\" หลังจากก่อตั้งศูนย์วิจัยหลายแห่ง\nน่าเสียดายที่สถานที่นี้ถูกไฟไหม้ในที่สุด",
  str_loading_h_desc93 = "ภายใต้อำนาจของศาสตราจารย์ Ulysses of Illumina หอจดหมายเหตุเก็บข้อมูลที่เป็นความลับไว้มากมาย\nไม่ทราบน้ำหนักของประวัติศาสตร์ที่อยู่เบื้องหลังข้อมูลบาง ๆ แต่ละชิ้น ทำให้ความลับที่แท้จริงถูกฝังอยู่",
  str_loading_h_desc94 = "วิธีการดัดแปลงที่ได้ผลที่สุดที่ค้นพบในตอนนี้คือการรวมวิธีการปรับปรุงต่างๆ ที่ได้รับการพิสูจน์แล้วว่าประสบความสำเร็จในเรื่องการทดลองเดียวกัน\nเราเพียงต้องการจิตใจที่แข็งแกร่งเพื่อสร้างผลลัพธ์ที่ประสบความสำเร็จ",
  str_loading_h_desc95 = "การฝึกทางทหารมีเป้าหมายเพื่อให้ผู้เข้าร่วมทุกคนได้เรียนรู้ ร่วมมือ และแข่งขันกัน\nมีสองขั้นตอน: การเตรียมหลักสูตรและการประเมินขั้นสุดท้าย\nทีมที่ชนะจะมีโอกาสเข้าร่วมการแข่งขันนิทรรศการกับจอมพลแห่งอิลลูมินา",
  str_loading_h_desc96 = "ความหมายของชัยชนะในการต่อสู้ไม่ควรสงสัย\nการต่อสู้แสดงถึงความมุมานะ ความรับผิดชอบ และความกล้าหาญที่แน่วแน่ของ Aurorian ในการเผชิญกับความมืดในขณะที่เราพยายามรักษาแสงแห่งความหวังโดยไม่สะดุด",
  str_loading_h_desc97 = "ลูกแก้วพิเศษที่พัฒนาโดยโบอาส ปรมาจารย์ด้านการทำนายในตำนานแห่งแดนเหนือ\nเมื่อเปิดใช้งานกับ Lumina แล้ว ระบบจะบันทึกเหตุการณ์ทั้งหมดที่เกิดขึ้นภายในช่วงที่กำหนดของตัวกระตุ้นโดยอัตโนมัติตลอดทั้งวัน\nผู้กระตุ้นจะต้องฉีด Lumina อีกครั้งเพื่อเคลื่อนย้ายตัวเองหรือผู้ที่สัมผัสเข้าไปใน Crystal of Eternal Memory และทบทวนสิ่งที่เกิดขึ้นในวันนั้น",
  str_loading_h_desc98 = "เพื่อเป็นการรำลึกถึงการมีส่วนร่วมของครอบครัว Schwartz ที่มีต่อ Lumopolis ผู้คนในเมืองจึงตัดสินใจที่จะจัดงานเฉลิมฉลองในวันที่บรรพบุรุษคนแรกของตระกูล Schwartz กลายเป็น City Lord เมื่อเวลาผ่านไป วันนี้กลายเป็นวันหยุดอย่างเป็นทางการของ Lumopolis\nครอบครัวชวาร์ตษ์มักจัดขบวนพาเหรด งานเฉลิมฉลอง งานเลี้ยงสังสรรค์ และกิจกรรมอื่นๆ ในวันนี้\nอย่างไรก็ตาม นับตั้งแต่เกิด Darkover Crisis ขนาดของงานเฉลิมฉลองก็ค่อยๆ ลดลง",
  str_loading_h_desc99 = "หลายพันปีก่อน บรรพบุรุษของตระกูล Kartima ได้เซ็นสัญญากับมังกร เป็นเวลานับพันปีที่ Dragonkin ที่ตื่นขึ้นได้ต้อนรับมังกรของพวกเขาเอง โดยสาบานว่าจะภักดีต่อกันและกันตลอดไปและยอมสละชีวิตและอำนาจเพื่อกันและกันอย่างไม่มีเงื่อนไข อย่างไรก็ตาม เพื่อที่จะผสมผสานเข้ากับสังคม Aurorian ตระกูล Kartima จึงมองว่า Dragonkin ที่ตื่นขึ้นเป็นคนนอกและห้ามไม่ให้พวกมันแพร่พันธุ์ เหตุใดทัศนคติของพวกเขาจึงเปลี่ยนไปอย่างกระทันหันจึงยังไม่ได้รับคำตอบ สิ่งเดียวที่ยืนยันได้คือ Mime Kartima ผู้นำตระกูลเรียกมังกรอีกครั้ง แต่ตั้งแต่วันนั้นเป็นต้นมาครอบครัวของพวกเขาก็เริ่มถดถอยลงอย่างสิ้นเชิง",
  str_loading_h_desc100 = "\"คุณอาจมีคำถามมากมายอยู่ในใจ และฉันไม่สามารถรับประกันได้ว่าจะได้คำตอบทั้งหมด การเดินทางครั้งนี้สั้น ดังนั้นฉันขอให้คุณรักษาประสบการณ์ที่หายวับไปนี้ไว้เหนือสิ่งอื่นใด\"",
  str_loading_h_desc101 = "โจชัวเกิดในครอบครัวที่มีการศึกษาสูง เป็นผู้หญิงที่โดดเด่นและมีความรู้ความสามารถ เป็นเลิศทั้งด้านวิชาการและการต่อสู้ พ่อของเธอเป็นนักวิชาการที่มีชื่อเสียงและเป็นผู้สอนแดเนียลเมื่อเขายังเด็ก นั่นคือวิธีที่พวกเขาพบกันและในที่สุดก็กลายเป็นคู่รักที่เอาชนะอุปสรรคทางชนชั้น เรื่องราวความรักของพวกเขาเป็นแบบคลาสสิกของยุคใหม่ของ Lumopolis ซึ่งเป็นแรงบันดาลใจให้ชายหนุ่มและหญิงสาวนับไม่ถ้วนด้วยความปรารถนาและความคาดหวังในอนาคต โจชัวดำเนินชีวิตตามความคาดหวังของผู้คน โดยนำเสนอตัวเองด้วยภาพลักษณ์ที่สมบูรณ์แบบราวกับพระมารดา ซึ่งเพิ่มความไว้วางใจทางการเมืองของผู้คนในตระกูลชวาร์ตษ์อย่างมาก\nนั่นคือสิ่งที่เกิดขึ้นจนกระทั่งเกิดอุบัติเหตุครั้งนั้น",
  str_loading_h_desc102 = "ครั้งหนึ่งเธอมีชื่อของเธอเอง แต่ตอนนี้เธอถูกเรียกว่า Joshua หรือ the Child of Montague ซึ่งแตกต่างจากผู้ดำรงตำแหน่ง City Lord อดีต City Lord พ่อของ Daniel เป็นทรราช ผ่านการกดขี่อย่างไม่เคยปรากฏมาก่อน เขาเปลี่ยนชนชั้นที่เสริมมุมมองของตนในลูโมโปลิสมาเป็นเวลาร้อยปี และกวาดล้างฝ่ายตรงข้ามอย่างโหดเหี้ยม Joshua เป็นผู้รอดชีวิตจาก House Montague\nผู้สมรู้ร่วมคิดบางคนโต้แย้งโดยอิงจากผู้รอดชีวิตเหล่านี้เพื่อจัดตั้งองค์กรโดยมีเป้าหมายเพื่อทำลายตระกูลชวาร์ตษ์ อย่างไรก็ตาม มันเป็นเพียงการต่อสู้ทางการเมืองอีกครั้งหนึ่งเพื่ออำนาจที่มากขึ้น และไม่มีใครสนใจเกี่ยวกับความเศร้าโศกของผู้รอดชีวิต ความโกรธที่ไม่รู้จักพอในสายตาของพวกเขาเป็นเพียงเครื่องมือในสายตาของผู้อื่น",
  str_loading_h_desc103 = "Denuo Wonderland ตั้งอยู่ในที่ลึกของทะเลทรายเรดีเซล และล้อมรอบด้วยหุบเขาที่สงบ ซึ่งเป็นขั้นตอนแรกของการพัฒนา Denuo Valley Resort\nเรดีเซล เวรนช์ มีบทบาทสำคัญในการออกแบบสถานที่น่าสนใจหลายแห่งในระหว่างการก่อตั้งสวนสนุก ทำให้มั่นใจได้ว่าทุกคนที่มาเยือนจะได้รับประสบการณ์ที่น่าสนใจและท้าทาย น่าสนใจว่าล้อหมุนยังคงเปิดให้บริการในช่วงค่ำคืน ทำให้แขกสามารถชมการแสดงดอกไม้ไฟอันโรแมนติกในขณะที่ขี่ล้อหมุน",
  str_loading_h_desc104 = "ตั้งอยู่ใกล้กับวันเดอร์แลนด์, โรงแรม Denuo Resort Hotel นำเสนอตัวเองเป็นปราสาทที่งดงามที่โผล่ขึ้นอย่างงามงวยจากวันเดอร์แลนด์\nภูมิทัศน์การทำสวนที่ไม่ซ้ำใครที่ประตูเข้าหน้า แสดงถึงสาระวัฒนธรรมของหุบเขา Denuo และความเคารพอย่างลึกซึ้งของนักพัฒนาต่อธรรมชาติ น่าสังเกตคืองานฝีมือที่ทำด้วยมือที่แสดงในล็อบบี้ใหญ่ของโรงแรมและระเบียง ซึ่งสร้างขึ้นโดยช่างฝีมือท้องถิ่นที่แสดงความสามารถที่ยอดเยี่ยม โรงแรมทั้งหลังเหมือนพิพิธภัณฑ์ บรรยายถึงประวัติศาสตร์ที่น่าสนใจของหุบเขา Denuo และตำนานที่มีเสน่ห์ของเทพี Denuo สำหรับแขกที่มีคุณค่าทุกคน",
  str_loading_h_desc105 = "หุบเขา Denuo Valley ยืนอยู่เป็นเพชรบานสะอาด โดยมีที่ตั้งทางภูมิศาสตร์ที่มีประโยชน์และภาพทิวทัศน์ที่สวยงาม\nตามตำนานท้องถิ่นเล่าว่า เคยมีภัยพิบัติจากธรรมชาติที่ลึกลับเกิดขึ้นที่หุบเขา ซึ่งทำลายหมู่บ้านทั้งหมด เหตุการณ์นี้เป็นความรำลึกที่ลึกซึ้งเกี่ยวกับธรรมชาติ ซึ่งกระตุ้นให้นักพัฒนาให้ความสำคัญกับการฟื้นฟูและการอนุรักษ์ที่มีความตระหนักถึงสิ่งแวดล้อมในระหว่างกระบวนการพัฒนา ตอนนี้หุบเขา Denuo Valley เติบโตอย่างเจริญรุ่งเรืองเป็นที่พิทักษ์ที่อุดมสมบูรณ์ ให้ที่พักอาศัยที่สมดุลกันสำหรับสัตว์ป่าและพืชที่น่าสนใจมากมาย",
  str_loading_h_desc106 = "โรงแรม Denuo Valley Resort มีระบบกรองอากาศที่ทันสมัย ในการลดเสียงรบกวนจากการหมุนเวียนอากาศ เจ้าของรีสอร์ทได้ปฏิบัติตามคำแนะนำของพนักงานและสร้างห้องใต้ดินเพื่อรองรับเครื่องจักรขนาดใหญ่\nน้อยคนที่รู้ว่า ด้านหลังประตูลับในห้อง มีอุโมงค์ลึกลับและซ่อนเร้น ภายในเก็บไว้สิ่งของที่มีประวัติศาสตร์ที่น่าสนใจและห่างไกล",
  str_loading_h_desc107 = "ประวัติของคุกอิลลูมินายาวนานตั้งแต่อดีต ก่อตั้งขึ้นเพื่อรักษาความปลอดภัยของสหพันธ์ ลงโทษพฤติกรรมอาชญากรรม และส่งเสริมการสะท้อนและฟื้นฟูใจให้กับผู้กระทำความผิด\nนักโทษจะถูกจัดเป็นหมวดหมู่และระดับต่าง ๆ ภายในคุกตามความอันตรายของตัวเอง ลักษณะของความผิด และระยะเวลาในการตัดสินความผิด โดยทั่วไปคณะกรรมการจะแต่งตั้งคณะบริหารคุกความมั่นคงสูงโดยตรง บุคคลที่เข้าสู่สถานที่ความมั่นคงสูงเหล่านี้ต้องมีเอกสารที่ถูกต้องและถูกต้อง",
  str_loading_h_desc108 = "ฐานที่มั่นลูโม่เป็นบ้านของผู้ถูกเนรเทศตั้งแต่แรกจากลูโมโพลิส รวมถึงอัศวิน ชาวบ้าน และลูกหลานของพวกเขา ซึ่งทั้งหมดถูกปกครองโดยขุนนางท้องถิ่นจากลูโมโพลิส ในปัจจุบันผู้ครองเมืองคือดีทริช ได้สะสมทรัพย์สินในปีหลังๆ ผ่านการทำเหมืองแร่ และสร้างกองทัพ ทำให้เขามีอิทธิพลอย่างมากในเมืองบนพื้นผิวของลูโมโพลิส\nภายในฐานที่มั่นลูโม่ มีโบสถ์ที่เป็นอิสระและภาคสาธารณูปโภค ซึ่งในช่วงสงครามจะมุ่งมั่นในการปกป้องชาวลูโมโพลิส",
  str_loading_h_desc109 = "ปล่อยออกมาโดยอิคลิพไซท์มัดบันเดิล โคลนเน่าเสียที่ปนเปื้อนกวาดล้างทั่วแผ่นดินเหมือนคลื่นสีดำ ทุกที่ที่สัมผัสกับพื้นดิน ความรุนแรงที่กัดกร่อนจะพุ่งขึ้นเสียงหวีด ตามด้วยพื้นดินที่พังทลายและพืชพันธุ์ที่เหี่ยวย่น กลิ่นของความเสื่อมสลายที่แรงขึ้นค้างอยู่ในอากาศขณะที่หนองน้ำขยายตัวอย่างรวดเร็ว จับกุมสิ่งมีชีวิตที่เป็นผู้บริสุทธิ์ในการครอบครองของมัน\n\nมัดบันเดิลซ่อนอยู่ในความลึกของโคลน สามารถเคลื่อนที่และโจมตีออโรเรียนอย่างคล่องแคล่ว อิคลิพไซท์ในทางกลับกัน ใช้กระแสพลังความมืดภายในโคลนเพื่อเพิ่มความสามารถในการโจมตี",
  str_loading_h_desc110 = "ตามที่เรารู้กัน วาร์ปน่าจะเป็นพลังความมืดที่มาจากอิคลิปส์ ทุกครั้งที่ทีมที่ติดอยู่ในวาร์ปเคลื่อนไปในระยะทางบางส่วน พวกเขาก็จะพบว่าตัวเองกลับมายังจุดเริ่มต้นอีกครั้ง ลักษณะที่แท้จริงของศิลปะนี้ยังคงเป็นปริศนา\n\nจุดเริ่มต้นนี้หมายถึงศูนย์กลางของพื้นที่กลมที่คงที่ ซึ่งจำกัดการเคลื่อนไหวของพวกเขาภายในรัศมี สิ่งนี้ทำให้ออโรเรียนรู้สึกว่าตัวเองวิ่งวนไปเรื่อยๆ แม้กระทั่งติดอยู่ในภาพลวงตาของวงวนอนันต์",
  str_loading_h_desc111 = "ฐานที่มั่นลูโม่เป็นบ้านของผู้ถูกเนรเทศตั้งแต่แรกจากลูโมโพลิส รวมถึงอัศวิน ชาวบ้าน และลูกหลานของพวกเขา ซึ่งทั้งหมดถูกปกครองโดยขุนนางท้องถิ่นจากลูโมโพลิส ในปัจจุบันผู้ครองเมืองคือดีทริช ได้สะสมทรัพย์สินในปีหลังๆ ผ่านการทำเหมืองแร่ และสร้างกองทัพ ทำให้เขามีอิทธิพลอย่างมากในเมืองบนพื้นผิวของลูโมโพลิส\nภายในฐานที่มั่นลูโม่ มีโบสถ์ที่เป็นอิสระและภาคสาธารณูปโภค ซึ่งในช่วงสงครามจะมุ่งมั่นในการปกป้องชาวลูโมโพลิส",
  str_loading_h_desc112 = "การออกแบบห้องขังของคุกอิลลูมินาปฏิบัติตามมาตรฐานและสิ่งอำนวยความสะดวกที่กำหนดไว้ เพื่อให้การดูแลนักโทษและมาตรการรักษาความปลอดภัยเป็นไปอย่างมีประสิทธิภาพ แต่ละห้องขังมีพื้นที่เก็บของสำหรับนักโทษเพื่อเก็บของส่วนตัว ตั้งแต่ตู้เก็บของขนาดเล็กถึงขนาดกลาง เสื้อผ้า และวัสดุอ่าน นอกจากนี้ยังมีระบบไฟฟ้าและระบายอากาศเพื่อความสะดวกสบายและความปลอดภัยภายในห้องขัง\n\nการตรวจสอบและบำรุงรักษาอย่างสม่ำเสมอเป็นสิ่งจำเป็นสำหรับห้องขังคุก เพื่อให้มาตรฐานความปลอดภัยและสุขอนามัยคงไว้ ข่าวลือบอกว่าสถานีนี้ยังกักกันผู้กระทำความผิดจากฝ่ายอื่นๆ ด้วย",
  str_loading_h_desc113 = "ดินแดนที่เหนือกว่าโลกของสิ่งที่มีตัวตน ดูเหมือนว่าสามารถเข้าถึงได้เฉพาะผ่านทางเส้นทางพิเศษ ผู้นำของทรู ออเดอร์อ้างว่าได้รับการเปิดเผยจากพระเจ้าแห่งความจริงที่ที่นี่เอง\nภายในดินแดนลับนี้ การแยกแยะแสงและความมืดกลายเป็นเรื่องยาก เนื่องจากมีสิ่งที่ส่องแสงสีแดงเข้มปรากฏขึ้นแทนสื่ออากาศปกติ ทำให้ออโรเรียนที่มาที่นี่ครั้งแรกรู้สึกความรู้สึกที่ไม่สามารถอธิบายได้ - การแขวนตัว ความกดอัดอย่างรุนแรง และเกินกว่านั้น",
  str_loading_N33_Cname_01 = "ดินแดนวันเดอร์แลนด์ Denuo",
  str_loading_N33_Cname_02 = "โรงแรมรีสอร์ท",
  str_loading_N33_Cname_03 = "หุบเขา Denuo",
  str_loading_N33_Cname_04 = "ชั้นใต้ดิน",
  str_loading_N33_Ename_01 = "วันเดอร์แลนด์ดีลักซ์ที่ตั้งอยู่ลึกซึ้งในทะเลทรายเรดีเซล",
  str_loading_N33_Ename_02 = "โรงแรมรีสอร์ทหรูหราอย่างยิ่ง",
  str_loading_N33_Ename_03 = "พื้นที่หุบเขาที่ไม่ได้พัฒนาใน Denuo Valley Resort",
  str_loading_N33_Ename_04 = "ห้องใต้ดินที่โรงแรม ซึ่งเป็นที่ตั้งของอุปกรณ์ระบายอากาศและมาตรการกันเสียง",
  str_loading_N33_des_01 = "Denuo Wonderland ตั้งอยู่ในที่ลึกของทะเลทรายเรดีเซล และล้อมรอบด้วยหุบเขาที่สงบ ซึ่งเป็นขั้นตอนแรกของการพัฒนา Denuo Valley Resort\nเรดีเซล เวรนช์ มีบทบาทสำคัญในการออกแบบสถานที่น่าสนใจหลายแห่งในระหว่างการก่อตั้งสวนสนุก ทำให้มั่นใจได้ว่าประสบการณ์ที่น่าสนใจและท้าทายสำหรับผู้มาเยือนทุกคน ในเวลาพิเศษ หลังจากที่พระอาทิตย์ตก แขกทั้งหมดจะได้รับเชิญให้ขึ้นล้อสวรรค์และชมการแสดงดอกไม้ไฟที่โรแมนติกมาก!",
  str_loading_N33_des_02 = "ตั้งอยู่ถัดจาก Denuo Wonderland, โรงแรม Denuo Resort แสดงให้เห็นเป็นปราสาทที่งดงามที่เกิดขึ้นอย่างงามงกรู้จากวันเดอร์แลนด์ ภูมิทัศน์การทำสวนที่ไม่ซ้ำใครที่ประตูเข้าหน้า แสดงถึงสาระวัฒนธรรมของ Denuo Valley และความเคารพอย่างลึกซึ้งของนักพัฒนาต่อธรรมชาติ น่าสังเกตคืองานฝีมือที่ทำด้วยมือที่แสดงในล็อบบี้ใหญ่ของโรงแรมและระเบียง ซึ่งสร้างขึ้นโดยช่างฝีมือท้องถิ่นที่แสดงความสามารถที่ยอดเยี่ยม โดยรวมแล้ว โรงแรมคล้ายกับพิพิธภัณฑ์ขนาดเล็ก บรรยายเรื่องราวของประวัติศาสตร์ที่อุดมสมบูรณ์ของหมู่บ้าน Denuo และตำนานของเทพี Denuo สำหรับแขกที่รักที่มีค่า",
  str_loading_N33_des_03 = "หุบเขา Denuo Valley ยืนอยู่เป็นเพชรบานสะอาด โดยมีที่ตั้งทางภูมิศาสตร์ที่มีประโยชน์และภาพทิวทัศน์ที่สวยงาม\nตามตำนานท้องถิ่นเล่าว่า เคยมีภัยพิบัติจากธรรมชาติที่ลึกลับเกิดขึ้นที่หุบเขา ซึ่งทำลายหมู่บ้านทั้งหมด เหตุการณ์นี้เป็นความรำลึกที่ลึกซึ้งเกี่ยวกับธรรมชาติ ซึ่งกระตุ้นให้นักพัฒนาให้ความสำคัญกับการฟื้นฟูและการอนุรักษ์ที่มีความตระหนักถึงสิ่งแวดล้อมในระหว่างกระบวนการพัฒนา ตอนนี้หุบเขา Denuo Valley เติบโตอย่างเจริญรุ่งเรืองเป็นที่พิทักษ์ที่อุดมสมบูรณ์ ให้ที่พักอาศัยที่สมดุลกันสำหรับสัตว์ป่าและพืชที่น่าสนใจมากมาย",
  str_loading_N33_des_04 = "โรงแรม Denuo Valley Resort มีระบบกรองอากาศที่ทันสมัย ในการลดเสียงรบกวนจากการหมุนเวียนอากาศ เจ้าของรีสอร์ทได้ปฏิบัติตามคำแนะนำของพนักงานและสร้างห้องใต้ดินเพื่อรองรับเครื่องจักรขนาดใหญ่\nน้อยคนที่รู้ว่า ด้านหลังประตูลับในห้อง มีอุโมงค์ลึกลับและซ่อนเร้น ภายในเก็บไว้สิ่งของที่มีประวัติศาสตร์ที่น่าสนใจและห่างไกล",
  str_loading_h_desc10004 = "อีฟเกิดและโตที่ทะเลทรายเรดดีเซล\nเธออาศัยอยู่ในชุมชนรถคาราวานกับพ่อที่แข็งแรงและแม่ที่ใส่ใจในการดูแล",
  str_loading_h_desc10005 = "อีฟเสมอสงสัยเกี่ยวกับชื่อถนนที่แปลกประหลาด... แต่ก็ดีนะ\nมีร้านค้าเจ๋งๆ และคลินิกของหมออยู่\nนั่นแหละที่สำคัญ!",
  str_loading_h_desc10006 = "ในความทรงจำของอีฟ เธอไม่เคยไปที่อื่นนอกจากพื้นที่ของกลุ่มรถคาราวานและถนนเทลสตรีท\nตอนนี้หลังจากที่เธอเปิดประตูเหล็กออกสู่โลกภายนอกด้วยตัวเอง พ่อแม่ของเธอคงจะให้บทเรียนที่รุนแรงถ้าพวกเขารู้\nแถม... ดูสิ โลกภายนอกนี่น่ากลัวจริงๆ ถูกต้องเลย",
  str_loading_h_desc10007 = "ทิวทัศน์เปลี่ยนไปอย่างต่อเนื่องต่อหน้าตาของเธอ เหมือนนิทานสวยงามที่ไม่สามารถจับต้องได้ และก็เปิดเผยเขี้ยวไฟอย่างกะทันหัน\nภาพลวงตาจะพังทลายเหมือนภูเขาในที่สุด ดังนั้นก็ต้องก้าวต่อไป...",
  str_loading_h_desc20011 = "\"ตั้งแต่เด็ก อิริดอนมีความปรารถนารุนแรงที่จะทำงานในศาลยุติธรรม\nเกี่ยวกับเหตุผลเฉพาะ... ดูเหมือนว่าแม้กระทั่งอิริดอนเองยังลำบากในการเรียกความทรงจำเหล่านั้น\"",
  str_loading_h_desc20012 = "\"ครอบครัวชั้นสูงมักจะไม่ส่งลูกของพวกเขาไปเรียนที่อุษาวิทยาลัยดอว์น; แทนที่จะเลือกจ้างตัวสอนส่วนตัวที่ยอดเยี่ยมมากที่สุด\nอย่างไรก็ตาม พ่อของอิริดอนเลือกที่จะไม่ปฏิบัติตามแนวคิดทั่วไป พ่อของเธอหวังว่าอิริดอนจะเรียนรู้วิธีที่จะโดดเด่นในหมู่คนทั่วไปตั้งแต่เร็ว ๆ นี้\"",
  str_loading_h_desc20013 = "\"จากบ้านของอิริดอนในสวน Lumopolis คุณต้องเดินผ่านทางเลี้ยววนและลง Stairway to the Skies ยาวๆ เพื่อไปยังลาน Lumopolis\nในสายตาของอิริดอน ลานนั้นไม่ดูแตกต่างจากสวนมากนัก\nอย่างไรก็ตาม สำหรับหลายคนในเพื่อนร่วมชั้นของอิริดอนในวันๆ ของการเรียน การปีนบันไดระหว่างชั้นลานและชั้นสวนเหมือนกับภารกิจที่เป็นไปไม่ได้\"",
  str_loading_h_desc20014 = "\"ในช่วงปีแรก ๆ ของอิริดอน เธอมีโอกาสน้อยที่จะได้สำรวจลูโมโพลิสชั้นล่าง\nตามคำบอกเล่าของพ่อของเธอ ที่นั่นเต็มไปด้วยขุนนางระดับล่างและคนธรรมดาที่ไม่สุภาพ ซึ่งเขากังวลว่าอาจมีผลกระทบต่อเด็กอย่างลูกของเขา\"",
  str_loading_h_desc20015 = "บนพื้นผิวน้ำที่สงบนิ่ง วงแหวนของริ้วน้ำสีทองเกิดขึ้นต่อกันหลายวง\nการสะท้อนในน้ำค่อยๆ เบี้ยวงอด้วยริ้วน้ำ หน้าตาเหมือนมีโลกที่แสนสุดมหัศจรรย์และสีสันอยู่ข้างใน",
  str_loading_h_desc80030001 = "คอนนอลลีชอบเรียกที่นี่ว่า \"ที่พำนัก\" มากกว่า \"บ้าน\"",
  str_loading_h_desc80030002 = "ถนนดูเหมือนจะถูกหุ้มด้วยหมอกลอยคลุมอยู่ใต้แสงกระพริบ ๆ ที่ลอยนวล พร้อมกับสิ่งมีชีวิตในน้ำและชาวบ้านที่คล้ายปลาเดินทางผ่านพวกเขา",
  str_loading_h_desc80030003 = "เมื่อเทียบกับห้องใต้หลังคาที่มืดและหนาว ที่นี่กระตุ้นความกระปรี้กระเปร่าให้คอนนอลลี และให้ความอบอุ่นและการสนับสนุน เสียที สำหรับคอนนอลลี ที่นี่คือความรู้สึกที่เป็นของตัวเองและที่จะกลับมา",
  str_loading_h_desc80030004 = "ที่นี่เป็นเมืองแฟนตาซีที่ตั้งอยู่ใต้ทะเลลึก คล้ายกับแดนมหัศจรรย์ในนิทาน\nคอนนอลลีหลงใหลในโลกน้ำนี้ และเธอจะสามารถสืบค้นผ่านกระแสน้ำที่ยุ่งยากและพบกับเพื่อนสนิทได้หรือไม่?",
  str_loading_h_desc80040001 = "ด้านตะวันตกของ Twin Pavilions Bay ถูกจัดการโดย Umbraton พื้นที่นี้คล้ายกับเมืองอื่น ๆ ของ Astra ในเรื่องของสไตล์สถาปัตยกรรม แต่ดูแปลกตามากขึ้นเนื่องจากการเพิ่มเติมของการตกแต่ง Longzhou",
  str_loading_h_desc80040002 = "ด้านทางตะวันออกของ Twin Pavilions Bay อยู่ภายใต้การควบคุมของ Lin Guild และมีเขต Little Longzhou ซึ่งถูกออกแบบให้ดูเหมือน Longzhou อยู่ข้างๆท่าเรือ",
  str_loading_h_desc80040003 = "Twin Pavilions Bay มีท่าเรือหลายแห่งพร้อมท่าเรือและเรือจำนวนมาก มันรับผิดชอบหน้าที่สำคัญในการดำเนินการขนส่งระหว่าง Astra และ Longzhou และเตรียมพร้อมที่จะรับเรือและสินค้าจากทั่วโลกเสมอ",
  str_loading_h_desc80040004 = "กาลครั้งหนึ่งนานมาแล้ว มีนักรบผู้อ่อนแอที่ถูกสาป ถือดาบใหญ่ที่สามารถสังหารปีศาจใดๆ และขจัดศัตรูทุกคน นักรบคนนี้ไม่ได้ยั่วยุด้วยเงินทองหรือชื่อเสียง และไปในภารกิจที่มุ่งมั่นเพียงอย่างเดียวเพื่อค้นหาและทำลายสาปทั้งหลายที่แปลกประหลาด หลังจากที่เธอสังหารสาปทั้งหมดของโลกแล้ว เธอจะสามารถนำพา \"ดอว์น\" ของตัวเองมาได้หรือไม่?",
  str_loading_h_desc80050001 = "ฮีโร่ที่กล้าหาญและตลกขึ้นมาจากพลเรือน ผู้นำของกองทัพ Northwind ที่เสมอมาพร้อมที่จะสละตัวเองเพื่อราชอาณาจักรและประชาชน แต่มีใครจริง ๆ ที่ได้ขุดเข้าไปในหัวใจของเขาเพื่อเข้าใจภาระที่เขาแบกบรรทุก ความทุกข์ที่เขาทนมานับพันปีหรือไม่?",
  str_loading_h_desc80050002 = "ก่อนที่ดินแดนนี้จะถูกรู้จักในนามแอสตรา มันเป็นที่ปกคลุมด้วยต้นกล้าของอารยธรรมออโรเรียนที่กระจายอยู่ ในนั้นมีราชวงศ์หนึ่ง ร่องรอยของมันได้ถูกล้างเป็นฝุ่นนานแล้ว แต่ตำนานของมันยังคงอยู่จนถึงวันนี้",
  str_loading_h_desc80050003 = "ยืนอยู่ในศูนย์กลางเมือง มีโครงสร้างที่งดงามที่บรรจุความเชื่อร่วมกันของทุกคนในราชอาณาจักร ไม่เหมือนกับลูโมโพลิสในปัจจุบัน สถานที่ศักดิ์สิทธิ์นี้ไม่ได้ปฏิเสธผู้ลี้ภัยที่ยากจนหมื่นปีที่แล้ว",
  str_loading_h_desc80050004 = "เฉพาะนักรบที่แท้จริงเท่านั้นที่สามารถเดินเข้าสู่สนาม โชว์พลังให้ฝูงชนเห็น รับรองการอาบน้ำด้วยดอกไม้และเสียงปรบมือ...",
  str_loading_N35_Cname_01 = "ซากโบราณใต้ดิน",
  str_loading_N35_Cname_02 = "นอร์ธแลนด์",
  str_loading_N35_Cname_03 = "ซาร์ยา",
  str_loading_N35_Ename_01 = "ซากโบราณจากยุคโบราณ",
  str_loading_N35_Ename_02 = "ดินแดนแห่งน้ำแข็งและหิมะ, แหล่งกำเนิดของชาวออโรเรียน",
  str_loading_N35_Ename_03 = "หญิงสาวแข็งตัว",
  str_loading_N35_des_01 = "ที่ตั้งนี้ไม่ปรากฏบนแผนที่ใด ๆ และขาดหายไปจากหนังสือแนะนำนักสำรวจส่วนใหญ่ ซากโบราณเหล่านี้เต็มไปด้วยอันตรายนับไม่ถ้วน หากเสมือนกับท้าทายให้ผู้ที่เข้าใกล้ไม่สามารถก้าวข้ามไปข้างหน้า มันเกือบจะรู้สึกเหมือนว่ายิ่งคุณเดินลึกเข้าไป คุณจะได้ยินเสียงกลไกที่ไม่มีอารมณ์และน่ากลัวมากพอที่จะทำให้บุคคลที่บุกรุกหันหลังหนี หากคุณยังคงเดินหน้า คุณจะค้นพบอะไรอยู่ในความลึก?",
  str_loading_N35_des_02 = "นอร์ธแลนด์เกิดขึ้นในหิมะ และยืนยงในน้ำแข็ง ภายใต้การคุ้มครองของราชินี ออโรเรียนได้คุ้มครองนอร์ธแลนด์มาหลายชั่วคนาย ตอนนี้เช่นเดียวกับในอดีต แม้ว่าพวกเขาต้องสละชีวิตหรือเผชิญความเหงาอันไม่น่าคิด พวกเขาก็ไม่เคยหลีกเลี่ยงความรับผิดชอบนี้ แต่อย่าลืมว่า ถึงแม้นอร์ธแลนด์จะเป็นแหล่งกำเนิดของออโรเรียน แต่ก็ไม่ใช่แหล่งกำเนิดของวัฒนธรรมทั้งหมด",
  str_loading_N35_des_03 = "ร้อยปีนั้นยาวกว่าอายุขัยส่วนใหญ่ของชาวออโรเรียน แต่สำหรับซาร์ยา ความเสียใจและความเสียใจของศตวรรษที่ผ่านมาดูเหมือนเป็นเมื่อวานนี้ ถูกกักขังในหีบน้ำแข็งที่ไม่ยอมที่จะหยุดนี้เป็นเวลาร้อยปี เธอถูกปลดปล่อยออกมาในที่สุด อย่างไรก็ตาม ใครจะช่วยปลดปล่อยเธอจากน้ำแข็งที่เยือกเย็นและความสงสัยที่ยังคงอยู่ลึกซึ้งในหัวใจของเธอล่ะ?",
  str_loading_N36_Cname_01 = "อัมบราตัน",
  str_loading_N36_Cname_02 = "ด่านอิลลูมินา",
  str_loading_N36_Cname_03 = "ทะเลทรายเรดีเซล",
  str_loading_N36_Ename_01 = "\"ศูนย์กลางธุรกิจและข้อมูล\"",
  str_loading_N36_Ename_02 = "ไล่ศัตรูไป โอบรับคนมีใจคอเดียวกัน",
  str_loading_N36_Ename_03 = "\"ทะเลทราย, อาณาจักรแห่งเสรีภาพที่แท้จริง\"",
  str_loading_N36_des_01 = "ตั้งอยู่เบื้องล่างเมืองลูโมโพลิส, อัมบราตันเป็นศูนย์กลางการค้าขายและการเงิน แต่ยังซ่อนอาชญากรรม คอร์รัปชัน และการหลอกลวง อยู่ด้วย อย่างไรก็ตาม เมื่อคุณสื่อสารกับชาวบ้านที่นี่ คุณจะพบว่าไม่ใช่ทุกคนในอัมบราตันมีศีลธรรมที่ล้มเหลว ที่นี่มีคนดีที่แท้จริงบางคน เช่น เจ้าของร้านอาหารของหลิว และเจ้าของร้านกิลด์คลาวด์โรเวอร์",
  str_loading_N36_des_02 = "นี่คือพื้นที่สำคัญในการป้องกันอิคลิพไซท์ ทหารที่ประจำที่นี่มีหน้าที่ไม่เพียงแค่ขับไล่การโจมตีของอิคลิพไซท์ แต่ยังคอยปกป้องอิลลูมินาและดำเนินการตรวจตราในพื้นที่ใกล้เคียงและเส้นทางการค้า บ้างครั้งทหารเหล่านี้จัดงานเลี้ยงเฉลิมฉลอง ไม่ว่าคุณจะมาจากที่ไหน ถ้าคุณไม่เคยก่อกวนหรือเคยช่วยเสียงอิลลูมินา พวกเขาก็ยินดีเชิญคุณเข้าร่วม",
  str_loading_N36_des_03 = "ในทะเลทรายเรดีเซลที่กว้างใหญ่ คุณจะพบสิ่งมีชีวิตแปลกประหลาดมากมายนอกจากอิคลิพไซท์ และคุณอาจเห็นมังกรตำนานบ้าง แต่ก็ยังคงคิดถึงเรดีเซล เวรนช์ ที่นำโดยซินซาเป็นอันดับแรก เมื่อพูดถึงทะเลทรายเรดีเซล สมาชิกของพวกเขาเดินทางข้ามทะเลทรายบ่อย ๆ ด้วยยานพาหนะของตัวเอง ใช้ชีวิตอย่างสนุกสนานและเพลิดเพลิน",
  str_loading_c_h_name10001 = "Twin Pavilions Bay",
  str_loading_c_h_name10002 = "ท่าเรือของ Twin Pavilions Bay",
  str_loading_e_h_name10001 = "ท่าเรือสำคัญที่เชื่อมต่อ Astra และ Longzhou",
  str_loading_e_h_name10002 = "ท่าเรือที่คึกคักนี้ไม่เคยหลับสลับ ด้วยเรือพ่อค้าที่จอดตลอดเวลา\nเรือเหล่านี้ พร้อมด้วยความหวังและความฝันของผู้คนที่สัมผัสได้ สะท้อนถึงการเปลี่ยนแปลงของชีวิตในที่นี่",
  str_loading_h_desc10001 = "ตั้งอยู่ที่ปากแม่น้ำทองคำ Twin Pavilions Bay เคยเป็นเมืองเล็ก ๆ ที่ไม่มีใครรู้จัก โชคชะตาของมันเปลี่ยนไปอย่างถาวรหลายปีที่แล้วเมื่อเรือพ่อค้าแรกจากหลงโจวมาถึง ซึ่งเริ่มกระบวนการเปลี่ยนแปลงให้กลายเป็นเมืองที่มีชีวิตชีวา\nเมืองนี้เป็นตัวอย่างที่น่าสนใจในเรื่องของความแตกต่าง: ครึ่งตะวันออก ตั้งอยู่ติดกับทะเลและท่าเรือ อยู่ภายใต้การดูแลของ Lin Guild โดยมีลักษณะสถาปัตยกรรมที่สะท้อนถึงสไตล์หลงโจว; ครึ่งตะวันตก ที่ถูกบริหารโดย Umbraton นำเสนอภาพสะท้อนของ Umbraton ในทิวทัศน์ของเมือง",
  str_loading_h_desc10002 = "ท่าเรือของ Twin Pavilions Bay ที่ถูกสร้างขึ้นด้วยคลื่นของเรือพ่อค้าที่ไม่หยุดนิ่ง มีถนนที่สะท้อนถึงสไตล์หลงโจว สดใสด้วยจังหวะชีวิตของตลาด\nร้านค้าขนาดเล็ก ที่เป็นที่พักผ่อนสำหรับกลุ่มนักเรือ แต่งเติมบรรยากาศของท้องถิ่น ระหว่างร้านอาหารราคาประหยัด โรงแรม และพ่อค้าตามถนนที่เกิดขึ้นเป็นครั้งคราว\nสะพานทอง ที่เป็นเงาที่ห่างไกล ทำหน้าที่เป็นสายเชื่อมระหว่างฝั่งตะวันออกและตะวันตกของเมือง",
  str_loading_N37_Cname_01 = "กิลด์เหนือเมฆ",
  str_loading_N37_Cname_02 = "คลินิกผู้ไร้นาม",
  str_loading_N37_Cname_03 = "หมาป่าดำ",
  str_loading_N37_Ename_01 = "หนึ่งในกิลด์ที่รุ่งเรืองและมีชื่อเสียงที่สุดในอัมบราตัน",
  str_loading_N37_Ename_02 = "คลินิกใต้ดินที่น่าเชื่อถือ",
  str_loading_N37_Ename_03 = "แก๊งที่เกิดขึ้นอย่างรวดเร็วในอัมบราตัน",
  str_loading_N37_des_01 = "กิลด์ที่ก่อตั้งโดยเชโอล\nภายในไม่กี่ปี กิลด์นี้เติบโตจากร้านค้าเคลื่อนที่ที่ไม่มีใครรู้จักเป็นหนึ่งในกิลด์ชั้นนำในอัมบราตัน\nกิลด์เหนือเมฆไม่ได้สามารถทำสิ่งนั้นได้โดยไม่มีเหตุผล สุดท้ายแล้วคุณสามารถซื้อสิ่งใดก็ตามที่คุณคิดได้ - และมากกว่านั้น - ที่นี่\nแม้กระทั่งคุณเองก็หลงทางในการเลือกซื้อของใช่ไหม?",
  str_loading_N37_des_02 = "คลินิกขนาดเล็กในสลัมที่ห่างไกลของอัมบราตันที่ไม่มีใครรู้ว่าเปิดมาเมื่อไหร่\nหมอและผู้ช่วยไม่เคยเปิดเผยชื่อของตัวเอง ดังนั้นทุกคนเรียกพวกเขาว่า \"หมอผู้ไร้นาม\" และ \"ผู้ช่วยผู้ไร้นาม\"\nแม้ว่าจะลึกลับ แต่คนยากจนใกล้เคียงยังค้นหาการรักษาในจำนวนมาก เนื่องจากค่าใช้จ่ายที่ไม่แพงและความเชี่ยวชาญของหมอ",
  str_loading_N37_des_03 = "ในอัมบราตัน มีแก๊งเล็ก ๆ นับไม่ถ้วนที่ก่อตั้งขึ้นเนื่องจากความจำเป็นในการปกป้องตัวเอง แต่แก๊งที่สามารถสร้างชื่อเสียงและขยายตัวอย่างต่อเนื่องเช่น Black Wolves นั้นมีน้อยและห่างหาย\nบางคนอ้างว่า Black Wolves ได้รับการสนับสนุนจากกิลด์ใหญ่คนหนึ่งเพื่อให้กระหายเช่นนี้ แต่แก๊งนั้นไม่เคยตอบคำถามเรื่องนี้โดยตรง\nบางที อาจเป็นเพราะไม่มีใครเคยถามคำถามนั้นอย่างเปิดเผยเลย",
  str_loading_N38_Cname_01 = "Twin Pavilions Bay",
  str_loading_N38_Cname_02 = "Shadowind",
