  str_loading_N38_Ename_02 = "เรือกลไกทางทะเล",
  str_loading_N38_des_01 = "เดิมเป็นหมู่บ้านตกปลาขนาดเล็กที่ตั้งอยู่ทางด้านตะวันออกของอัมบราตัน แต่กลายเป็นท่าเรือการค้าเมื่อมีเรือพ่อค้าหลงโจวมาถึง ในปัจจุบัน ด้านตะวันตกของ Twin Pavilions Bay ถูกจัดการโดยอัมบราตัน และมีสไตล์สถาปัตยกรรมที่คล้ายกันกับเมืองอื่น ๆ ในแอสตรา ส่วนด้านตะวันออกอยู่ภายใต้การควบคุมของกิลด์หลิน โดยมีถนนและท่าเรือที่มีธีมตะวันออก คล้ายกับสไตล์ของหลงโจว",
  str_loading_N38_des_02 = "เรือทะเลชั้นนำที่ได้รับการสนับสนุนและก่อตั้งโดย Lin Guild\nออกแบบโดยการเพิ่มเครื่องจักรของ Ye Kingdom ทำให้มีความทนทานและพลังเหนือเรือแบบดั้งเดิม นอกจากนี้ยังมีอุปกรณ์สำหรับการกู้ซากใต้น้ำ ยานพาหนะนี้จะขนนักเร่งนำทาง Xuan Ji และคนอื่นๆ เข้าสู่ทะเลลึก สำรวจโลกที่ไม่เคยมีใครเข้าไปมาก่อน",
  str_loading_N39_Cname_01 = "กิลด์เหนือเมฆ",
