  str_loading_N39_Ename_02 = "สถานที่สำหรับความบันเทิงของชนชั้นสูง",
  str_loading_N39_Ename_03 = "กิลด์ที่กำลังฝ่าฟันขึ้นมาและตั้งอยู่นอกเมืองอัมบราตัน",
  str_loading_N39_des_01 = "กิลด์ที่ถูกก่อตั้งโดยเชโอล ภายในเวลาไม่กี่ปี กิลด์นี้ได้ขยายตัวจากร้านค้าเคลื่อนที่ที่ไม่มีชื่อเสียงเป็นหนึ่งในกิลด์ที่มีอำนาจมากที่สุดในอัมบราตัน\nในปัจจุบัน กิลด์เหนือเมฆยังมีเรือบินขนาดใหญ่ที่รวมการเดินทาง ช้อปปิ้ง การพักผ่อน และการท่องเที่ยว ทั้งหมดในที่เดียว!\nความสามารถของกิลด์เหนือเมฆในการสร้างสรรค์ความสำเร็จที่ยิ่งใหญ่นี้ไม่ได้มาโดยไม่มีเหตุผล สุดท้ายแล้ว สินค้าทุกชนิดที่คิดได้ (และแม้กระทั่งที่คิดไม่ได้) สามารถซื้อผ่านพวกเขาได้แม้แต่คุณยังหลงทางในการเลือกที่มีขนาดใหญ่ขนาดนี้ ไม่ใช่หรือ?",
  str_loading_N39_des_02 = "บนพื้นผิวระหว่าง Umbraton และ Lumopolis มีแผ่นดินขนาดใหญ่ที่เคยรู้จักในนาม \"The Pit\" นานมาแล้ว มันเคยเป็นสนามละครของกีฬาเลือดสาดสำหรับชนชั้นสูงของ Lumopolis ที่นี่ พวกเขาจะส่งผู้ร้ายที่แข็งแกร่งหนึ่งร้อยคนเข้าไปใน The Pit และบังคับให้พวกเขาฆ่าฟันฆ่าตากันเพื่อความสนุกสนานของพวกเขา คนสุดท้ายที่ยืนอยู่จะได้รับการยกเว้นความผิดทั้งหมด รวมถึงรางวัลอุดมสมบูรณ์จากขุนนางที่สนับสนุนพวกเขา ในเวลาหนึ่ง จำนวนหนึ่งของนักสู้ได้ปรากฏขึ้นจากอัมบราตัน นักสู้ที่เข้าสู่ \"เดอะพิต\" ด้วยความสมัครใจเพื่อค้นหาความมั่งคั่งและความรุ่งเรือง\nก่อนวิกฤติดาร์คโอเวอร์ ขุนนางได้เริ่มถอยหลังไปยังความปลอดภัยของลูโมโปลิสอย่างช้า ๆ และ \"เดอะพิต\" ก็เริ่มตกต่ำลง แต่อย่างไรก็ตาม วัฒนธรรมของ \"ความแข็งแกร่งเหนือทุกอย่าง\" ยังคงอยู่และกลายเป็นสถานการณ์ปกติในอัมบราตัน ไม่นานหลังจากนั้น สนามการต่อสู้ที่ผิดกฎหมายที่พยายามจำลองความรุ่งเรืองของ The Pit ก็เกิดขึ้นทั่วทั้งเมือง ดึงดูดความสนใจจำนวนมาก",
  str_loading_N39_des_03 = "กิลด์ขนาดใหญ่ที่ปรากฏขึ้นนอกเหนือจากอัมบราตัน หัวหน้าของพวกเขาคือผู้หญิงลึกลับที่แทบจะไม่เคยแสดงตัวในที่สาธารณะ\nกิลด์มักจะไม่เห็นการเติบโตอย่างรวดเร็วในระดับนี้โดยไม่พึ่งพาความได้เปรียบทางภูมิศาสตร์และการขนส่งของอัมบราตัน แต่ Continental Guild ก็สามารถทำได้อย่างไรสักอย่าง\nดังชื่อของมัน Continental Guild มีอิทธิพลที่ยืดไปถึงเมืองเล็ก ๆ และหมู่บ้านในทุกที่ในแผ่นดินแอสตรา",
  str_loading_c_h_name121 = "ห้องทดลองของอัลกอล",
  str_loading_c_h_name122 = "ห้องโบราณของอิลลูมินา",
  str_loading_c_h_name123 = "เหนือเมืองแกนน่อน",
  str_loading_c_h_name124 = "คลังศูนย์",
  str_loading_c_h_name125 = "รอยแยกที่ไม่ทราบที่มา",
  str_loading_c_h_name126 = "แม่น้ำที่สะอาดใส",
  str_loading_e_h_name121 = "สำนักงานของอิลลูมินาที่ทั้งเป็นที่ที่มีเทคโนโลยีสูงและเป็นกันเอง",
  str_loading_e_h_name122 = "ห้องปฏิบัติการอิลลูมินาเก่าที่ติดตามมาด้วยความสงสัยและความขัดแย้ง.",
  str_loading_e_h_name123 = "เหมือนรุ่งอรุณ แต่ก็เหมือนพระอาทิตย์ตกดิน",
  str_loading_e_h_name124 = "คลังสินค้าลับที่ไม่ได้บันทึกไว้ใน Illumina.",
  str_loading_e_h_name125 = "รอยแยกที่แตกสลายและจมลงไปในความลึกและความมืดที่ไม่ทราบจำนวน",
  str_loading_e_h_name126 = "แม่น้ำที่เงางามและลวงลับอย่างลึกลับ",
  str_loading_h_desc121 = "ห้องปฏิบัติการที่ผสมผสานระหว่างสถาปัตยกรรมนี้เป็นส่วนตัวของนักวิทยาศาสตร์อิลลูมินา อัลกอล สถานที่ที่ผสมผสานระหว่างเทคโนโลยีและความสะดวกสบายนี้เป็นสิ่งที่หาได้ยากในเมืองแกนน่อนที่มีการควบคุมโดยทหาร\nแม้ว่าห้องปฏิบัติการนี้จะไม่สอดคล้องกับกฎระเบียบอิลลูมินาสำหรับการจัดการที่อยู่อาศัย แต่ไม่มีใครคัดค้านเนื่องจากเฟอร์นิเจอร์ส่วนใหญ่ถูกสร้างขึ้นโดยอัลกอลโดยใช้วัสดุที่ถูกนำมาใช้ใหม่ มีการบอกว่าใครก็ตามที่มาเยี่ยมห้องปฏิบัติการนี้จะสามารถนอนหลับสนิทได้ด้วยเสียงฮัมของอุปกรณ์อิเล็กทรอนิกส์ในพื้นหลัง",
  str_loading_h_desc122 = "หลายปีที่แล้ว เมื่อทรัพยากรน้อยลงในสหพันธ์อิลลูมินา นักวิทยาศาสตร์ที่มีความคิดรุ่นใหม่และมีความคิดที่สูงส่ง ได้สนทนาเกี่ยวกับอนาคตของออโรเรียนทั้งวันทั้งคืนในห้องปฏิบัติการขนาดเล็กนี้\nถ้ามีจุดสิ้นสุดสำหรับออโรเรียน ทุกการสนทนาและคำถามที่ถูกยกขึ้นนั้นเพื่อหยุดการเกิดเหตุการณ์นั้น อย่างไรก็ตาม โต๊ะทำงานในห้องปฏิบัติการ พื้น และโครงสร้างเหล็กที่เคยเป็นสะท้อนของความรู้นั้นได้หายไปแล้ว",
  str_loading_h_desc123 = "เมื่อมีใครบางคนในอิลลูมินามองขึ้นไปที่เมืองใต้ดิน พวกเขาก็รู้ว่าแสงสว่างที่สามารถทะลุผ่านได้นั้นเป็นของขวัญจาก \"โลกที่มีวัฒนธรรม\" สำหรับแกนน่อน ครั้งหลังครั้ง แกนน่อนได้ทนทานการโจมตีของอิคลิพไซท์ ทำให้ประชาชนของอิลลูมินาพยายามขับไล่ผู้บุกรุก หวังว่าวันหนึ่งพวกเขาจะสามารถกลับมาที่ผิวดินและได้สนุกสนานในแสงแดดอย่างสงบสุข\nอย่างไรก็ตาม แสงสว่างนี้ก็เป็นการลาทิ้งจากโลกที่มีวัฒนธรรม ด้วยวิกฤติการณ์ดาร์คโอเวอร์ที่กำลังจะมาถึง อิลลูมินาจะสามารถยืนหยัดเพื่อปกป้องบ้านเกิดของพวกเขาได้หรือไม่?",
  str_loading_h_desc124 = "โกดังที่ว่างเปล่าและหนาวเย็นมากมาย มีกลิ่นของสารละลายที่แรง\nพื้นที่โล่งนี้ดูเหมือนจะเคยเก็บอาวุธที่ใหญ่แต่เป็นอันตราย\nผู้ที่เดินเข้ามาครั้งแรกไม่เคยรู้สึกตัวเองน้อยนิดเท่านี้\n\nเครื่องจักรที่ทำงานอย่างต่อเนื่องเป็นสะพานเชื่อมระหว่างอดีตและปัจจุบัน\nเข้าใกล้โต๊ะทางชีววิทยาที่ซับซ้อนและมีเสียงร้องของเครื่องจักร\nคุณจะได้ยินเสียงร้องของชีวิตที่น่าสงสารมากมายที่ได้รับการ \"เกิดใหม่\" ที่นี่",
  str_loading_h_desc125 = "รอยแตกยักษ์ที่ไม่มีสัญญาณชีวิตใด ๆ จากการตรวจสอบรอยแตก มันคือปรากฏการณ์ Dark Zone โบราณ การระเบิดที่รุนแรงในอดีตก็เป็นหลักฐานที่ชัดเจน ทิ้งเฉพาะหลุมที่ดำเสมอ ลูกกระเดือกที่ลอยลำและดินที่ถูกไหม้ บนผิวดิน รอยแตกกำลังแตกออกไปยิ่งไกล\nเกิดอะไรขึ้นที่นี่? หรืออะไรกำลังเกิดขึ้นอยู่?",
  str_loading_h_desc126 = "ความมืดที่ไม่มีที่สิ้นสุดและความเงียบสงบเหมือนเวลาหยุดนิ่ง อย่างกะทันหัน แม่น้ำที่ลึกลับเริ่มขยายตัวจาก \"ขอบฟ้า\" ที่ห่างไกลเหมือนในภาพวาด นี่คือทิวทัศน์แฟนตาซีที่ไม่เคยปรากฏบนแผนที่แอสตรามาก่อน การปรากฏของมันทำให้ความเป็นจริงของโลกมีความลึกลับมากขึ้น\nที่มาของแม่น้ำนี้อยู่ที่ไหน? มันจริงหรือไม่? ทำไมเมื่อคุณกวนน้ำ การเปลี่ยนแปลงที่ไม่คาดคิดจะเกิดขึ้นที่ไหนสักที่ในโลกนี้?",
  str_loading_c_h_name127 = "อาณาจักรจี",
  str_loading_c_h_name128 = "วิกฤตชายฝั่งทะเลในอาณาจักร Ji",
  str_loading_c_h_name129 = "เทศกาลฤดูใบไม้ผลิ",
  str_loading_e_h_name127 = "อาณาจักรการค้าและการขนส่งทางน้ำ",
  str_loading_e_h_name128 = "หญิงสาวมังกร, อิคลิพไซท์, และตราประทับ",
  str_loading_e_h_name129 = "ปีใหม่หลงโจว",
  str_loading_h_desc127 = "อาณาจักรขษะในตะวันตกของหลงโจว มีแม่น้ำที่ตัดกันเป็นเส้นทางมากมาย ด้วยเหตุนี้ ระบบขนส่งทางน้ำของมันพัฒนาอย่างดี มีเส้นทางเรือในส่วนใหญ่ของหลงโจว ทำให้เป็นศูนย์กลางขนส่งตั้งแต่ยุคโบราณ การค้าขายเจริญรุ่งเรือง ทำให้เป็นศูนย์กลางเศรษฐกิจ นครหลวงของมันคือเมืองฮาวจิน ซึ่งมีความเจริญรุ่งเรืองมาก และเป็นที่อยู่ของครอบครัวพ่อค้าร่ำรวยมากมาย รวมถึงกิลด์หลิน",
  str_loading_h_desc128 = "หลายร้อยปีที่แล้ว ซากของอิคลิพไซท์ที่ถูกฝังอยู่ในน้ำทะเลชายฝั่งของราชอาณาจักรจิ ได้ทำลายพันธุกรรมของพี่น้องมังกรของ Dragon Maiden ซึ่งเป็นมังกรสีดำ มังกรสาวจึงต้องทำลายมันอย่างรุนแรง ปิดถ้ำทะเลเพื่อป้องกันการไหลเวียนของพลังอิคลิพไซท์ ด้วยความประมาทของราชอาณาจักรในพิธีกรรมใหญ่ ตราประทับได้ถูกทำลาย ทำให้อิคลิพไซท์ได้เสรีที่จะก่อความวุ่นวาย ราชอาณาจักรจิ ถึงแม้จะเคลื่อนย้ายกำลังของมันเพื่อตอบสนอง แต่ก็ได้รับความเสียหายอย่างมาก",
  str_loading_h_desc129 = "เทศกาลฤดูใบไม้ผลิเป็นเทศกาลที่สำคัญที่สุดบนทวีปหลงโจว ราชวงศ์จะจัดงานเลี้ยงสำหรับแขกที่เคารพนับถือในขณะที่พลเมืองรวมตัวกันเพื่อสันทนาการและการติดตามข่าวสาร ในราชอาณาจักรจี ชาวบ้านจัดงานวัด สักการะแม่มารดามังกร และขับไล่สัตว์ปีนี้ในระหว่างเทศกาล หวังว่าจะมีสุขภาพและโชคดีในปีที่จะถึง มีพ่อค้าบางรายจ้างอสูรเพื่อจัดการแสดงที่มีธีมเกี่ยวกับพิธีไล่สัตว์ ทำให้เริ่มต้นปีใหม่มีความสนุกสนานเพิ่มขึ้น",
  str_loading_c_h_name205 = "ห้องควบคุมเครื่องบินของสหพันธรัฐอิลลูมินา",
  str_loading_c_h_name206 = "ชายแดนที่ถูกหิมะปิดบัง",
  str_loading_c_h_name207 = "ถ้ำแดนชายแดน",
  str_loading_c_h_name208 = "แท่นบูชาบรรพบุรุษ",
  str_loading_c_h_name209 = "ปราสาทเชิงเทิน",
  str_loading_e_h_name205 = "เย็นจัดและเป็นศูนย์กลาง กลิ่นหอมของโลหะยังคงส่งออกมาในอากาศ",
  str_loading_e_h_name206 = "ชายแดนตะวันตกเฉียงเหนือของนอร์ธแลนด์ที่มีการเข้ามาเยี่ยมชมน้อยมาก",
  str_loading_e_h_name207 = "ถ้ำโบราณที่ถูกปกคลุมด้วยชั้นๆ ของน้ำแข็ง",
  str_loading_e_h_name208 = "พื้นที่ศักดิ์สิทธิ์ลึกลับที่ถูกปกป้องโดยหมู่เผ่าหมาป่าหิมะตลอดหลายรุ่นครั้ง",
  str_loading_e_h_name209 = "ปราสาทโบราณที่ถูกทำลายโดยการสงคราม",
  str_loading_h_desc205 = "แม้ว่าจะไม่กว้างขวางเท่าห้องควบคุมของ Colossus แต่ที่นี่ก็เพียงพอสำหรับทีมสำรวจขนาดกลาง ผนังของมันถูกปกคลุมด้วยแผงควบคุมเครื่องมือที่ซับซ้อนและจอภาพ บันทึกค่าต่าง ๆ และข้อมูลของเครื่องบินอย่างถูกต้อง ในขณะที่ตัวชี้บนแผงควบคุมเครื่องมือสั่นไหวอย่างต่อเนื่อง เสียงเครื่องจักรที่มีจังหวะอ่อนๆดูเหมือนจะส resonates กับความถี่ของการคำนวณเครื่องจักรยักษ์ใน Illumina Undercity ที่ลึกลับ",
  str_loading_h_desc206 = "ภายใต้ท้องฟ้าที่มืดมิดของหิมะ ทะเลทรายหิมะที่เคยไม่มีที่สิ้นสุดดูเหมือนจะมีทางสิ้นสุด ภูเขาสูงๆยืนอยู่เหมือนกำแพงในทางไกล แบ่งแยกสถานที่นี้จากโลกภายนอก แต่ป่าสนหิมะที่เงียบเหงากำลังเผชิญกับการโจมตีที่น่ากลัวอีกครั้ง ด้วยบ้านที่ถูกทำลายเป็นซาก สนหิมะที่ถูกหักอย่างไม่เห็นแก่ตัว และหิมะที่ถูกเปื้อนด้วยจุดๆของเลือดสีแดงดำใหญ่ๆ... ดูเหมือนว่าไม่มีใครรู้หรือสนใจเกี่ยวกับสิ่งมีชีวิตที่อาศัยอยู่ที่นี่",
  str_loading_h_desc207 = "ถ้ำหนาวเย็นมีโครงสร้างที่ซับซ้อนและเป็นเขาวงศ์ บางผนังน้ำแข็งยื่นตรงขึ้น ในขณะที่ผนังอื่นๆ ต่ำและแคบ บังคับผู้ที่ผ่านไปให้โค้งคลาน แสงสว่างอ่อนๆ ซัดผ่านผลึกน้ำแข็ง สร้างเงาที่มีจุดจุดและห่มถ้ำด้วยเงาที่สงบและสีเงิน-ขาว คอลัมน์น้ำแข็งที่สูงและขรุขระ พร้อมกับดอกไม้น้ำแข็งบนผนังถ้ำ กลายรูปเป็นรูปร่างที่แปลกประหลาด พร้อมรับครั้งที่แสงออโรราลงมา",
  str_loading_h_desc208 = "ภายในความลึกลับของถ้ำมืด แสงสว่างทะลุผ่านเพดานลงมาส่องบนแท่งบูชาด้านล่าง ดังนักสร้างแท่งบูชาที่รอการตื่นของสามต้นไม้ศักดิ์สิทธิ์ หน้าแท่งบูชามีแผ่นหินที่ถ่ายทอดตำนานของ \"สามต้นสน\" โดยมีตัวอักษรโบราณ สองประตูที่มีรูปปั้นหน้าจอห์นที่สภาพเสื่อมสภาพยืนเฝ้า ซึ่งเป็นสัญลักษณ์ของการคุ้มครองแท่งบูชาของเผ่าพวกเขา ผู้ใหญ่บอกว่า แม้ดูเหมือนจะแข็งตัวมาหลายพันปี แต่พรของต้นไม้ศักดิ์สิทธิ์ยังคงอยู่",
  str_loading_h_desc209 = "ลมพัดเข้าสู่ช่วงลึกของถ้ำ โดยผ่านปราสาทโบราณที่สูงอยู่บนพื้นดิน ในพายุหิมะที่รุนแรง ภายในปราสาทส่องสว่างด้วยไฟ ผู้ป้องกันปราสาทเคลื่อนไหวอยู่ จิตใจของพวกเขาสูงส่งเมื่อพวกเขาเดินหน้าเพื่อรักษาคำสาบานโบราณของพวกเขา การตะโกนของพวกเขาและการชนของอาวุธได้ขับไล่ความหนาวจากน้ำแข็งและหิมะ ทำให้พวกเขาลืมความรุนแรงของยุคนี้",
  str_loading_N45_Cname_01 = "ฐานของเรดีเซล เวรนช์",
  str_loading_N45_Cname_02 = "ทางเดินเลย์ไลน์",
  str_loading_N45_Cname_03 = "ภูเขาไฟกึกก้อง",
  str_loading_N45_Ename_01 = "ฐานชั่วคราวที่เรดีเซล เวรนช์ ตั้งขึ้นหลังจากที่พวกเขาหยุดการเคลื่อนที่ มีประสิทธิภาพและสะดวกสบาย",
  str_loading_N45_Ename_02 = "เส้นทางเลี่ยววนใต้ทะเลทรายเรดีเซล\nทางผ่านลึกลับเหล่านี้เชื่อมต่อกับเส้นเลย์ไลน์ของทะเลทราย",
  str_loading_N45_Ename_03 = "ภูเขาไฟใต้ดินที่มีเสียงดังอยู่เสมอ แปลกที่มันพึ่งปะทุเมื่อ 15 ปีที่แล้ว",
  str_loading_N45_des_01 = "เนื่องจากสภาพแวดล้อมที่โหดร้ายของทะเลทราย เรดีเซล เวรนช์ มักจะถูกบังคับให้ออกจากโอเอซิสเพื่อค้นหาวัสดุอุปกรณ์ และเมื่อ Lepidoz หยุดพัก พวกเขาจะสร้างฐานชั่วคราวที่ที่พวกเขาอยู่ทันที",
  str_loading_N45_des_02 = "ใต้ทะเลทรายเรดีเซลมีทางเดินที่คดเคี้ยวและลึกลับอย่างไม่สามารถอธิบายได้ที่ขยายไปทุกทิศทาง และรวมกันเรียกว่าทางเดินเลย์ไลน์\nไม่มีใครรู้ว่าพวกเขาเกิดขึ้นอย่างไร แต่ทางเดินดูเหมือนจะมีอยู่มานานและเคยถูกพัฒนาเป็นระยะ แต่ทุกอย่างถูกทำลายโดยการเริ่มต้นของภัยพิบัติต่าง ๆ",
  str_loading_N45_des_03 = "ภูเขาไฟที่ร้องเสียงดังคือภูเขาไฟที่อันตรายที่สุดในทะเลทรายเรดีเซล มันมักจะหลับสนิท แต่มันมักจะทำเสียงดังเสมอ ในครั้งเดียวที่มันระเบิด มันได้ทำลายฐานที่ตั้งเดิมของทะเลทรายเรดีเซล\nสมาชิกของเรดีเซล เวรนช์กลัวภูเขาไฟนี้และไม่ได้กลับไปที่นั่นมาหลายปี\nตามคำเล่าที่กระจายอยู่ในหมู่พวกเขา คำว่าเสียงดังนั้นเป็นของอิคลิพไซท์ที่อาศัยอยู่ในน้ำหินเหลว",
  str_loading_N46_Cname_01 = "เขี้ยวที่ซ่อนอยู่",
  str_loading_N46_Ename_01 = "อาร์เคดอัมบราตัน\nสัญลักษณ์ของชุมชนเกมของแอสตรา",
  str_loading_N46_des_01 = "อาร์เคดที่ก่อตั้งโดยเกมเมอร์ที่มีประสบการณ์ มันเริ่มต้นจากเป็นสโมสรขนาดเล็กที่บริการชาวออโรเรียนที่ชื่นชอบเครื่องเล่นเกมส์โบราณ ตามที่เกมมากขึ้นและถูกพัฒนา นักเล่นเกมจากทั่วแอสตร้าถูกดึงดูดมา และเร็วๆ นี้อาร์เคดกลายเป็นสถานที่หลักที่ชุมชนเกมเมอร์ชอบไปเล่นเกม",
  str_loading_N47_Cname_01 = "ฐาน: ระดับพื้นผิว",
  str_loading_N47_Cname_02 = "ฐาน: เส้นทาง",
  str_loading_N47_Cname_03 = "ฐาน: แคซซึม",
  str_loading_N47_Cname_04 = "ฐาน: ซากโบราณ",
  str_loading_N47_Cname_05 = "หัวหอก",
  str_loading_N47_Ename_01 = "เวลาและมูลนิธิล่มสลายไปด้วยกัน",
  str_loading_N47_Ename_02 = "เสียงสะท้อนจากพื้นที่ของเครื่องมือที่ถูกทิ้งทิ้ง",
  str_loading_N47_Ename_03 = "จุดแตกหักของความทรงจำและจุดเปลี่ยนของชีวิต",
  str_loading_N47_Ename_04 = "สถานที่พักผ่อนของหัวเข็มยานโคลอสซัสที่ยับเยิน",
  str_loading_N47_Ename_05 = "ที่แฟนท่อมแห่งอดีตยังคงหลอกหลอน",
  str_loading_N47_des_01 = "ฐานทดลองที่ถูกอิลลูมินาฝังซ่อนไว้ หากไม่ได้มีพลังอันยิ่งใหญ่ของบาร์ตันที่สร้างช่องทางเข้ามา มันอาจจะยังคงซ่อนอยู่\nรากฐานที่แข็งแรงนั้นสร้างความแตกต่างอย่างชัดเจนกับกำแพงเมืองอิลลูมินาที่แข็งแกร่งในปัจจุบัน แต่อย่างไรก็ตาม ความลับของอดีตเสมอมาเป็นเวลาของพวกเขา รอคอยบุคคลที่เหมาะสมที่จะเปิดเผยพวกเขา\nสถานที่นี้ได้เป็นพยานการฝึกฝนอย่างมีความหลงใหลและการทดลองที่โหดร้าย รวมถึงการต่อสู้อย่างสิ้นหวังและการกบฏที่รุนแรง",
  str_loading_N47_des_02 = "เครื่องดนตรีที่ถูกทิ้งไว้ทำหน้าที่เป็นทหารยามที่ขวางทางผู้บุกรุก มีเครื่องดนตรีที่ยังทำงานอยู่หลายตัวที่แอบมองออกมาจากซากปรักษา ทำให้ความคิดของผู้บุกรุกสับสนในขณะที่กำลังวางแผนอย่างลับๆ นี่คือถ้ำมืดที่แยกเสียงร้องทุกข์ และทางลึกที่ทดสอบความฝันของคนที่ฝัน ถ้าคุณได้ยินเสียงที่เรียกคุณ อาจควรหยุดและดูว่ามันเป็นอดีตที่คุณทิ้งไว้ที่กำลังติดต่อคุณหรือไม่",
  str_loading_N47_des_03 = "นั่นเป็นช่วงเวลาที่ยากลำบากไม่ทนได้ ซึ่งฝังประสบการณ์ชีวิตที่ถูกทอดทิ้งไปอย่างมากมาย ข้างบนของห้วยลึกคือที่สูงของผู้ชนะ และด้านล่างของมันคือสุสานของผู้ที่ถูกเสียสละ ผู้ใดที่ปรารถนาจะคว้าความยุติธรรมจากอดีตที่ไม่ยุติธรรมนี้ ต้องกระโจนลงไปในขุมนรก เมื่อร่างกายของพวกเขาถูกเผาไหม้และไม่มีเนื้อเยื่อที่จะถูกทำลายอีกต่อไป พวกเขาจึงสามารถบินสูงได้ตลอดกาล",
  str_loading_N47_des_04 = "ที่สุดของฐานทดลองนั้นมีโคลอสซัสที่มีหางที่หักและยังมีความรู้สึกที่จางๆอยู่ความมุ่งมั่นที่ยืนยงของมันดูเหมือนจะสั่งให้ส่วนที่กระจัดกระจายของมันประกอบตัวเองขึ้นมาใหม่ในขณะที่มันรอคำสั่งจากนักเดินทางเพื่อเดินทางไปยังบ้านเก่าของมัน ดูเหมือนว่ามันจะอยู่ที่นี่นานกว่าประวัติศาสตร์ทั้งหมดของ Illumina และความจริงของการทดลองนี้ถูกเปิดเผยโดยอุปกรณ์ทดลองทั้งหมดที่สร้างขึ้นรอบ ๆ มันในภายหลัง",
  str_loading_N47_des_05 = "การทำธุรกรรมที่อันตรายนี้คือคำใบ้สุดท้ายที่มีให้กับนักสำรวจทั้งหมด ผ่านเครื่องมือพิเศษ คนสามารถเห็นข้อมูลห้องควบคุมหลักที่เหลืออยู่ของ Spearhead แม้ว่าห้องจะเป็นซาก แต่โครงสร้างภายในของมันยังคงเป็นระเบียบและราบรื่นมากกว่าโซรอซ และแผงควบคุมแต่ละตัวปล่อยออร่าที่อันตราย มันมาจาก Dark Zone หรือไม่? ผู้นำทางของมันจะเป็น Caelestite หรือไม่?",
  str_loading_N48_Cname_01 = "เมืองวาราคี",
  str_loading_N48_Cname_02 = "การมาถึงของความจริง",
  str_loading_N48_Cname_03 = "สุสานวาราคี",
  str_loading_N48_Cname_04 = "ปราสาทของวิลเฮล์ม",
  str_loading_N48_Cname_05 = "วัดแห่งความจริง",
  str_loading_N48_Ename_01 = "บ้านเกิดของตระกูลแวมไพร์",
  str_loading_N48_Ename_02 = "การประชุมใหญ่ของทรู ออเดอร์",
  str_loading_N48_Ename_03 = "สถานที่พักผ่อนของบรรพบุรุษวาราคี",
  str_loading_N48_Ename_04 = "ปราสาทที่หนาวและโดดเดี่ยวบนหน้าผา",
  str_loading_N48_Ename_05 = "ห้องใหญ่สีเลือดที่น่าขนลุกและศักดิ์สิทธิ์",
  str_loading_N48_des_01 = "ครอบครัวแวมไพร์, สายพันธุ์ออโรเรียนที่เป็นเอกลักษณ์, ได้พำนักอยู่ในเมืองวาราคีนานแล้วตามที่ตำนานบอกมา พวกเขาชอบความมืดและมีความใคร่ในเลือด อายุของพวกเขายืดยาว, มักจะรักษาลักษณะที่พวกเขามีตอนที่เชื้อสายของพวกเขาตื่น\nลูกหลานของครอบครัวนี้รับมรดกพลังใหญ่ของบรรพบุรุษของพวกเขาเมื่อเชื้อสายของพวกเขาตื่น อย่างไรก็ตาม, ความทรงจำที่เจ็บปวดที่มาพร้อมกับพลังนี้คือค่าที่พวกเขาต้องรับผิดชอบ.",
  str_loading_N48_des_02 = "ทุกๆ สามปี คืนแบบนี้จะเกิดขึ้น—เมื่อเที่ยงคืน ระฆังของวัดแห่งความจริงจะดังขึ้น และหอระฆังสูงๆ จะยืดตัวและสูงขึ้นไปยังดวงจันทร์ดวงจันทร์ ส่องสีเลือดแดง ยืนหยัดในท้องฟ้า ดั่งว่าเจ้าของความจริงกำลังฟังการสารภาพในวัด และแบ่งปันความรุ่งโรจน์และความลับของครอบครัว ลูกศิษย์ของความจริงสวมชุดพิธีและแบกโลงศพเดินทางผ่านถนน ร้องเพลงบทสวดมนต์ชื่อของพระเจ้าอย่างเคารพ รอคอยการมาถึงของเจ้าของความจริง",
